(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-essa-evolutionary-strategies-for-sca-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-1\">一 · 现场：一个长尾请求把整条生成流水线拖进空转</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-2\">二 · 耦合的数学形态：批完成时间由最大值决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-3\">三 · 奖励与验证器：被生成挤住的第二类推理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-4\">四 · 量化档位把问题放大：NVFP4 采样稳定性成为独立风险项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-5\">五 · 为什么非改不可：三个不可调和的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-6\">六 · 旧方案留下的接口缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-7\">七 · 请求长度分布与组批口径：主批按 token 预算，长尾进低优先级队列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-8\">八 · 并发上限与 SLO：用 KV 命中率和队列深度做反馈信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-9\">九 · 奖励池与生成的重叠：队列解耦带来的独立扩容口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-10\">十 · 权重同步的短窗口：staleness 是吞吐与样本质量的交换项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-11\">十一 · 量化档位与采样稳定性：NVFP4 与 FP8 的选择要挂到监控上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-12\">十二 · 失败模式的可观测形态与阈值缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-13\">十三 · 采样路径上的算子切分：从 GEMM 到采样头</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-14\">十四 · 数据类型逐层拆解：FP16/BF16/FP8/NVFP4 的位预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-15\">十五 · 累加精度与误差传播：谁在放大谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 如何改变代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-17\">十七 · 量化选型与 SLO 的耦合：把采样稳定性做成可监控项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-18\">十八 · 失败模式与 kernel 级防线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-19\">十九 · 显存账本的三个账户与可复算预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-20\">二十 · 分页与前缀哈希：把 KV 从会话私有变成块共享</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-21\">二十一 · 压缩与复用：量化 KV、跨请求复用、以及不能压的地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-22\">二十二 · 卸载与带宽瓶颈：HBM3e 之外的那条路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-23\">二十三 · 与调度、权重同步的耦合：预算表怎么随版本滚动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-24\">二十四 · 前缀命中率跌下来之后：ESSA 显存账本的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-25\">二十五 · 连续批处理的组批单位：token 预算而非请求数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-26\">二十六 · chunked prefill：把预填切片塞进解码步的缝隙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-27\">二十七 · 优先级与抢占：长尾队列的深度就是 SLO 的刻度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-28\">二十八 · 分离式预填/解码与奖励池的独立扩容</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-29\">二十九 · 权重同步的短窗口：staleness 是吞吐的抵押品</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-30\">三十 · 尾延迟的压缩路径：三个可调点的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-31\">三十一 · 切分拓扑：ESSA 推理侧的四条并行轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-32\">三十二 · NVLink 5 与 NVSwitch：机架内带宽如何改变切分选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-33\">三十三 · All-Reduce 与 All-to-All 的瓶颈判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-34\">三十四 · NIXL 传输：解耦之后样本怎么走</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-35\">三十五 · 通信成为瓶颈的三个现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-36\">三十六 · 切分与量化的联合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-37\">三十七 · 精度塌陷：NVFP4 采样漂移的三种可观测形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-38\">三十八 · OOM 与 KV 击穿：预填尖峰的定位路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-39\">三十九 · 批抖动与尾延迟：长尾队列深度的反馈控制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-40\">四十 · 静默降级：奖励池反压与 staleness 窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-41\">四十一 · 监控面板与回滚顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-42\">四十二 · 诊断的边界：未量化的阈值与可核验项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-43\">四十三 · 失效链的耦合点：从KV击穿到staleness失控</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-44\">四十四 · 口径先于数字：ESSA 推理侧的可核验边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-45\">四十五 · 硬件档位与量化：NVFP4 采样稳定性是独立监控项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-46\">四十六 · 指标怎么读：TTFT、TPOT 与吞吐的分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-47\">四十七 · 哪些提升不可比：解耦收益与耦合基线的错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-48\">四十八 · 失败模式对应的口径缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-49\">四十九 · 边界不在算法在口径：ESSA 推理收益的可比性判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-50\">五十 · 迁移到非对齐任务：ES 采样器的可替换边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-51\">五十一 · 换模型：前缀共享与权重同步的耦合变化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-52\">五十二 · 量化迁移：NVFP4 采样稳定性的领域敏感性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-53\">五十三 · 规模上限：长尾队列与批利用率的相互作用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-54\">五十四 · 不适用的场景与失败模式迁移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-55\">五十五 · 迁移的工程判断：先改队列，再改精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-56\">五十六 · 迁移边界：ES 解耦架构在换模型、换领域、换档位时的失效条件</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入rollout引擎，按提示词前缀哈希查询KV缓存，命中则复用前…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按请求长度分布与并发上限组批，长尾样本进入低优先级队列，避免拖尾阻塞主…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">批量生成完成后，样本送入独立奖励模型/验证器serving池打分，池与…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">打分结果进入异步流水线，训练侧按版本号消费；权重同步在短窗口内允许旧版…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">监控KV命中率、批利用率与长尾队列深度，按SLO反馈调节批大小与并发上…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-1\">一 · 现场：一个长尾请求把整条生成流水线拖进空转</h3>\n<p>设想一个已经上线的对齐服务：入口是长短混合的提示词，短的一两百 token，长的几千 token，还夹着系统提示前缀高度重合的模板化请求。旧栈的典型形态是把 rollout 引擎和训练进程绑在同一个作业里——训练侧发出一个梯度步的节奏，rollout 侧就按这个节奏生成一批样本，生成完立刻回灌，训练完立刻再生成。看起来耦合得很紧、数据很新鲜，代价却全部落在推理侧。</p>\n<p>具体机制是这样的：生成批的大小由训练侧的步节奏决定，而不是由请求长度分布决定。一个批里混进几条超长提示词，这几条样本的预填与解码就把整个批的完成时间往后拖，主批里已经生成完的短样本只能等着，等长尾样本收尾才能一起交回训练侧。这段时间里 SM 的占用率被长尾样本的低并行度锁死，GPU 处于“有事做但做不满”的空转状态。批利用率下降不是抽象指标，它直接表现为单位时间内产出的有效样本 token 数下降，也就是吞吐下降；而训练侧还在等这一批，梯度步被拉长，整条流水线的节拍被最慢的那条样本定义。</p>\n<p>第二个代价在显存与算力上。每个请求都要独立预填自己的提示词前缀，即便这些前缀在系统提示层面大量重复。重复预填意味着重复的注意力计算与重复写入 KV，KV 缓存被同一段前缀的多个副本占满，能留给解码的显存变少，并发上限被迫压低。第三个代价是奖励模型与验证器：它们和生成挤在同一批 GPU 上，打分请求与生成请求争抢显存与 SM，生成高峰时打分排队，打分高峰时生成停摆，两边都无法按自己的 SLO 独立扩容。</p>\n<p>把这三件事写成一句工程判断：旧栈把“生成怎么调度”“前缀怎么复用”“打分怎么服务”三个本可独立决策的问题，压缩成了一个由训练步节奏统一驱动的耦合系统。耦合带来的不是效率，而是把最慢样本的延迟、最重复前缀的算力、最拥挤的显存全部转嫁到整条流水线上。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-2\">二 · 耦合的数学形态：批完成时间由最大值决定</h3>\n<p>设一个生成批含 $n$ 条请求，第 $i$ 条请求的预填加解码时间为 $t_i$，则这个批的完成时间不是平均意义上的 $\\frac{1}{n}\\sum t_i$，而是</p>\n<div class=\"formula\">$$T_{\\text{batch}}=\\max_{i\\in[1,n]} t_i,\\qquad U_{\\text{batch}}=\\frac{\\sum_i t_i^{\\text{eff}}}{n\\cdot T_{\\text{batch}}}$$</div>\n<p>其中 $U_{\\text{batch}}$ 是批利用率，$t_i^{\\text{eff}}$ 是第 $i$ 条请求实际占用计算资源的时间。只要长度分布有长尾，$\\max$ 就会显著大于均值，利用率随长尾长度单调下滑。旧栈的问题在于 $n$ 由训练步节奏给定，调度器没有权力把长尾样本挪出主批，于是 $\\max$ 项无法被隔离，长尾的拖尾直接变成整批的空转。</p>\n<p>再看前缀重复的代价。设前缀哈希为 $h$，命中率为 $\\rho$，单次预填的前缀计算量为 $C_{\\text{pre}}$，则不做共享时一个批的前缀计算量为 $n\\cdot C_{\\text{pre}}$，做共享后约为 $(1-\\rho)\\cdot n\\cdot C_{\\text{pre}}$，同时 KV 显存占用从 $n\\cdot M_{\\text{pre}}$ 降到 $(1-\\rho)\\cdot n\\cdot M_{\\text{pre}}$ 量级（未计 LRU 淘汰的驻留策略）。$\\rho$ 在模板化系统提示场景下本可以很高，但旧栈缺少统一的缓存机制描述，命中率既不可监控也不可调度，重复预填的算力与显存代价被默默计入每个请求的固定开销。</p>\n<p>一个具体例子：某批 32 条请求，其中 28 条为短请求、各耗时约一个单位，4 条长请求各耗时约八个单位。按 $\\max$ 计，批完成时间为八个单位，批利用率被压到不足三成；若把 4 条长请求移入低优先级队列、主批按固定 token 预算推进，主批完成时间回到一个单位量级，长尾在后台继续消化，同样的 GPU 时间产出更多有效样本。这个例子不含任何实测数字，只说明 $\\max$ 与均值之差就是旧栈白付的代价。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-3\">三 · 奖励与验证器：被生成挤住的第二类推理</h3>\n<p>对齐阶段的推理负载不止生成一种。奖励模型与验证器要对每条样本打分或校验，它们是独立的模型、独立的显存需求、独立的批形态——打分请求通常是“整段样本一次前向”，与自回归解码的批形态完全不同。旧栈把它们塞进同一个服务实例，结果是两类负载互相反压：生成批未完成时打分请求排队，打分池满时生成请求被阻塞。更糟的是，打分本可以与下一批生成重叠，耦合结构却要求“先生成完、再打分完、再训练”，三段串行，任何一段的尾延迟都传导到下一段。</p>\n<p>从容量角度看，这是两个应该独立扩容的资源池被强行共享了一个容量上限。生成侧的并发上限受 KV 显存约束，打分侧的并发上限受奖励模型权重与激活约束，两者的瓶颈不在同一个维度上；用一个上限同时管两件事，必然有一边长期欠配。旧栈的调度器没有队列级的解耦描述，也就无法回答“打分池该扩到多大”这种容量规划问题。</p>\n<p>还有一个隐性代价：权重同步。训练侧更新权重后，生成侧必须切换到新权重才能保证样本新鲜，但切换意味着在途请求要么被打断重算、要么等切换完成才能继续。旧栈缺少版本号机制，切换往往表现为一次全局停顿，停顿窗口内 GPU 空转，窗口长度与在途请求数量成正比。这段停顿既不产出样本也不产出梯度，是纯粹的吞吐损失。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-4\">四 · 量化档位把问题放大：NVFP4 采样稳定性成为独立风险项</h3>\n<p>到了 Blackwell 档位，问题不是变小而是变多。B200/B300 与 GB200 NVL72 的显存与带宽提升让更大的批、更长的 KV 成为可能，但量化方案的选择引入了新的不确定性：NVFP4 的采样稳定性在材料中未给出实测，只能作为待核验的部署代价处理。旧栈把量化当成一个全局开关，生成、打分、验证共用同一套数值策略，一旦 NVFP4 在某类长尾样本上出现采样分布偏移，受影响的不只是生成质量，还包括奖励模型对这批样本的打分——而打分又被训练侧直接消费，误差沿流水线放大。</p>\n<p>这里的推理系统代价是双向的：NVFP4 带来更高的有效吞吐与更低的显存占用，但采样稳定性若不可监控，就等于把风险藏进了样本质量里。旧栈没有把“采样稳定性”作为独立监控项的位置，因为它连生成与打分都没有分池，更谈不上按池选择量化方案。工程上合理的做法是让量化方案随档位与负载类型选择，把稳定性指标与 KV 命中率、长尾队列深度并列放进监控面板，而不是用一个全局开关一次性决定。</p>\n<p>另一个被放大的点是 KV 缓存击穿。前缀哈希共享一旦缺失，长提示词的预填会在请求到达时集中爆发，形成预填尖峰，挤占解码的显存与算力。档位越高、批越大，尖峰的绝对幅度越大，SLO 的尾延迟越难守住。旧栈既没有前缀缓存，也没有长尾分级队列，尖峰只能靠压低并发上限来吸收，而压低并发又直接砍掉吞吐——这是一个没有出口的循环。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-5\">五 · 为什么非改不可：三个不可调和的约束</h3>\n<p>把旧栈的痛点收敛成三条互相冲突的约束，就能看清为什么局部调参救不了它。</p>\n<ul>\n<li><b>批大小约束</b>：批大小由训练步节奏给定，调度器无法按请求长度分布与 token 预算重新组批，长尾拖尾无法隔离，$\\max$ 项永远压在批完成时间上。</li>\n<li><b>显存约束</b>：生成与打分共享显存池，KV 无前缀共享，重复预填既吃算力又吃显存，并发上限被两头挤压，任何一侧扩容都要从另一侧抢资源。</li>\n<li><b>新鲜度约束</b>：权重切换缺少版本号与短窗口机制，在途请求与权重更新只能二选一，切换停顿直接变成吞吐损失；而若为了新鲜度频繁切换，停顿次数上升，吞吐进一步下降。</li>\n</ul>\n<p>这三条约束的共同点是：它们都不是单点问题，而是调度权、资源池、同步机制三处结构缺失的叠加。在旧栈里调大批大小会加剧长尾拖尾，调小批大小会降低批利用率；给打分池多分显存会压缩 KV 容量；缩短权重切换周期会增加停顿。每一个局部动作都在另一处制造新代价，这就是“非改不可”的工程含义——不是旧方案不够快，而是它的决策变量被耦合结构锁死，没有可调的自由度。</p>\n<p>一个具体场景可以说明锁死的程度：监控面板上看到长尾队列深度上升、批利用率下降，旧栈能做的只有下调并发上限，而下调并发会让主批变小、批利用率进一步下降，形成正反馈式的恶化。若换成 rollout 引擎按固定 token 预算组主批、长尾进低优先级队列、KV 前缀按哈希命中复用、打分走独立池并与生成重叠，同样的监控信号对应的动作就变成“调低长尾队列的并发权重”而不是“砍掉整条流水线的并发”，决策空间从一维变成多维。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-6\">六 · 旧方案留下的接口缺口</h3>\n<p>从系统接口的角度看，旧栈缺的不是某个算子，而是三组描述：生成侧与训练侧之间的<b>节拍接口</b>（谁决定批大小、谁决定何时消费）、生成侧与打分侧之间的<b>队列接口</b>（反压信号如何传导、容量如何独立规划）、权重更新与在途请求之间的<b>版本接口</b>（旧权重请求如何完成、staleness 如何界定）。这三组接口缺失，使得任何推理优化都只能做在单点算子上，无法做在流水线结构上。</p>\n<p>ESSA 的推理侧正是从这三组接口切入：rollout 引擎按请求长度分布组批并维护前缀 KV 缓存，把批大小的决定权从训练步节奏手里拿回来；奖励模型与验证器作为独立 serving 池、通过队列与生成解耦，让打分与下一批生成重叠；权重同步用版本号广播加短窗口，允许在途请求以旧权重完成，把切换停顿换成可控的 staleness。这三件事各自对应旧栈的一处结构缺失，也各自对应一个可监控项——KV 命中率、长尾队列深度、staleness 窗口长度。至于 ES 如何替代策略梯度式 rollout、使这套解耦在算法上成立，属于后续部分的范围；本部分只需确认：旧栈的痛点不是调参能解的，而是接口层面的缺口。</p>\n<p>最后落在一个具体机制上：当下调并发上限这个动作从“全局砍吞吐”变成“只作用于长尾队列”，监控面板上的批利用率与 KV 命中率就成为可操作的反馈信号，而不是事后解释。这就是旧方案与新结构之间真正的分界线——不是某个数字的快慢，而是调度器手里有没有可用的决策变量。</p>\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-7\">七 · 请求长度分布与组批口径：主批按 token 预算，长尾进低优先级队列</h3>\n<p>ESSA 推理侧的第一层是 rollout 引擎，它面对的不是单一序列，而是一个长短混合的请求池。论文卡给出的机制是：组批时不按“请求条数”对齐，而按固定 token 预算推进主批，长尾样本进入低优先级队列。这个选择直接决定了测量口径——批大小必须同时报告三个量：主批的 token 预算、主批实际填充的 token 数、低优先级队列的深度。只报 batch size 的条数没有意义，因为同样 32 条请求，长度分布从短提示主导切到长提示主导，token 预算占用可以差出数倍，GPU 的有效占用率也随之改变。</p>\n<p>可核查的组批伪代码思路是：对到达请求按前缀哈希分组，命中前缀 KV 的请求先入主批，未命中的长提示走预填后再入批；主批累积 token 数达到预算上限即封批发射，剩余请求按长度降序进入低优先级队列，等待下一轮或由空闲 SM 补位。这里的关键代价是显存与带宽：主批 token 预算越大，单批激活与 KV 写入的峰值显存越高；预算越小，批利用率越低、单位 token 的权重读取摊销越差。在 Blackwell 上，权重读取受 HBM 带宽约束，批太小会让每个 token 都要重读一遍权重，吞吐掉得比预期快。</p>\n<p>具体例子：一个对齐批次里系统提示统一、用户问题长短不一。前缀哈希命中后，系统提示的 KV 只预填一次，主批里每条请求只补自己的后缀 token；而未命中的长提示若直接塞进主批，会把整批的完成时间拉到它的长度上，短请求全部陪跑。把长提示挪到低优先级队列，主批的完成时间由中位长度决定，队列深度成为拖尾的显式度量。测量口径上，应记录每批的 token 预算、实际填充率、低优先级队列深度的时间序列，以及主批发射间隔——这四者共同刻画“拖尾是否在吃 GPU 空转”。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-8\">八 · 并发上限与 SLO：用 KV 命中率和队列深度做反馈信号</h3>\n<p>并发不是越高越好。论文卡的机制是并发上限按 SLO 反馈调节，调节信号是 KV 命中率与长尾队列深度。理由是显存：并发上升意味着在途请求的 KV 同时驻留，前缀共享能压低重复预填，但每条请求的后缀 KV 仍线性增长；一旦 KV 缓存被击穿，命中率骤降，预填尖峰反过来抢占解码的算力，SLO 尾部延迟立刻恶化。因此并发上限应被看作一个由显存预算和命中率共同约束的量，而不是固定常数。</p>\n<p>可核查的测量口径需要把 SLO 拆成可观测的分位数：首 token 延迟（预填完成时间）、每输出 token 间隔（解码节奏）、端到端完成时间。对 rollout 引擎而言，真正约束容量的是首 token 延迟与批发射节奏，因为生成是批量推进的，单条请求的尾延迟会被批内最慢成员拉长。公式化地写，单批的有效吞吐近似为</p>\n<div class=\"formula\">$$\\text{Throughput}_{\\text{batch}} \\approx \\frac{B_{\\text{tok}}}{T_{\\text{prefill}} + N_{\\text{out}}\\cdot T_{\\text{decode}}}$$</div>\n<p>其中 $B_{\\text{tok}}$ 是主批实际填充的 token 数，$N_{\\text{out}}$ 是批内最长输出长度，$T_{\\text{prefill}}$ 与 $T_{\\text{decode}}$ 分别是预填与单步解码时间。这个式子说明：拖尾不是“多等一会”，而是把分母里的 $N_{\\text{out}}$ 拉大，直接摊薄整批吞吐。工程判断是，当长尾队列深度持续超过主批一轮的 token 预算时，下调并发上限比继续加并发更能保住 SLO——因为加并发只会让 KV 驻留更多、命中率更低。</p>\n<p>具体例子：监控面板上 KV 命中率从高位滑落、长尾队列深度同步抬升，这两个信号同时出现时，说明预填正在与解码争抢算力。此时把并发上限下调一档，让主批先消化命中前缀的请求，未命中的长提示在队列里等待，预填尖峰被削平，首 token 延迟的分位数回落。代价是短期的队列等待时间上升，但批利用率与解码节奏恢复稳定。这个权衡必须用分位数曲线来验证，而不是看平均延迟。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-9\">九 · 奖励池与生成的重叠：队列解耦带来的独立扩容口径</h3>\n<p>奖励模型与验证器是独立 serving 池，与 rollout 引擎通过队列解耦，打分与下一批生成重叠。这一层的测量口径与生成层完全不同：生成层看 token 吞吐与批利用率，奖励层看每秒打分样本数、排队长度与打分延迟分位数。两者解耦的意义在于容量可以分开扩——奖励池扩容不会挤占 rollout 引擎的显存，反之亦然。若把打分耦合进生成进程，奖励模型的权重与激活会和 KV 缓存争同一块 HBM，长尾样本打分慢时整条流水线都被拖住。</p>\n<p>可核查的重叠口径是：记录每个生成批的完成时刻与对应样本进入奖励池的时刻，两者之差即排队等待；再记录奖励池的并发打分批大小与打分延迟分位数。重叠是否真的发生，取决于奖励池在生成批完成前是否已有空闲容量。若奖励池长期排队，说明它的扩容滞后于生成吞吐，反压会传导回 rollout 引擎的队列，表现为长尾队列深度异常增长——这是失败模式“奖励池排队反压生成”的可观测形态。</p>\n<p>具体例子：一批长短混合样本生成完毕，短样本先出队进入奖励池打分，长样本还在解码；奖励池按自己的批大小独立组批，不等整批生成结束。这样打分与下一批生成在时间上重叠，GPU 的算力在生成与打分两个池之间轮转，而不是串行等待。代价是两池各自的批利用率都不会拉满，但端到端流水线的空转窗口被压缩。测量上应报告“生成-打分重叠率”，即打分请求中有多少比例是在生成未完成时被处理的。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-10\">十 · 权重同步的短窗口：staleness 是吞吐与样本质量的交换项</h3>\n<p>训练侧以异步流水线消费 rollout 结果，权重更新后通过版本号广播到 rollout 引擎，短窗口内允许在途请求以旧权重完成。这是一个明确的吞吐换新鲜度的机制：若要求权重切换时所有在途请求立即中止重跑，GPU 上正在解码的批全部作废，吞吐出现周期性凹陷；允许旧版本完成，则切换是平滑的，但产出的样本带有 staleness。staleness 的上界论文卡未给出，因此它必须作为独立监控项，而不是默认无害。</p>\n<p>可核查的口径是给每个样本打上权重版本号与生成起始时刻，统计样本版本号与训练侧当前版本的差值分布，以及旧版本样本在总样本中的占比。公式化地，短窗口长度 $W$ 与在途请求平均完成时间 $\\bar{T}_{\\text{req}}$ 的关系决定了旧版本样本比例：</p>\n<div class=\"formula\">$$p_{\\text{stale}} \\approx \\frac{\\bar{T}_{\\text{req}}}{W + \\bar{T}_{\\text{req}}}$$</div>\n<p>窗口越短，旧版本样本越少，但权重切换越频繁地打断在途批，吞吐损失越大；窗口越长，吞吐越平滑，旧版本样本比例越高。这个式子是定性口径，具体数值需实测。工程判断是：staleness 监控必须与样本质量指标联动——若旧版本样本的奖励分数分布与新版本出现系统性偏移，说明窗口过长已经影响对齐信号，此时应缩短窗口，接受吞吐凹陷。</p>\n<p>具体例子：权重版本号广播后，rollout 引擎不立即丢弃在途批，而是让它们以旧版本完成并把版本号写进样本元数据；训练侧消费时按版本号分组，监控面板上同时显示旧版本样本占比与奖励分数分布。若占比抬升而分数分布未漂移，窗口可维持；若分数分布漂移，则窗口需收紧。这是把“短窗口换吞吐”从一句机制描述变成可观测、可回退的操作。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-11\">十一 · 量化档位与采样稳定性：NVFP4 与 FP8 的选择要挂到监控上</h3>\n<p>硬件档位按 B200/B300/GB200 NVL72 分档，量化方案在 NVFP4 与 FP8 间按采样稳定性选择。这里的推理系统代价是双向的：NVFP4 降低权重与激活的显存占用、提高 HBM 带宽的有效利用率，从而允许更大的批或更长的 KV 驻留；但采样稳定性是待核验项，论文卡明确未给出 NVFP4 下采样稳定性的实测。因此量化选择不能只按吞吐收益拍板，必须把采样稳定性作为独立监控项挂到面板上。</p>\n<p>可核查的口径是：在同一请求分布下对比两种量化档位的输出分布偏移——用固定提示词集合重复采样，统计同一提示下多次采样的结果一致性、以及奖励分数的方差。若 NVFP4 下方差显著抬升，说明采样稳定性受损，即便吞吐更高也不应作为默认档位。测量必须区分预填与解码两个阶段，因为量化的误差在长解码链上会累积，短提示可能看不出差异，长尾长输出才会暴露。</p>\n<p>具体例子：GB200 NVL72 档位下，rollout 引擎按前缀哈希命中复用 KV，主批 token 预算拉大；此时若切到 NVFP4，显存余量允许更高并发，但长尾队列里的长输出样本在解码末段出现采样抖动，奖励分数方差抬升。监控面板上“采样稳定性”与“长尾队列深度”并列，前者恶化时回退到 FP8，牺牲一部分并发换回分布一致性。这个回退路径本身就是量化档位选择的工程判断依据，而不是事后补救。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-12\">十二 · 失败模式的可观测形态与阈值缺口</h3>\n<p>论文卡列出的失败模式有三类：KV 缓存击穿导致预填尖峰、奖励池排队反压生成、权重同步窗口过长引入旧版本样本。三者在监控上各有形态：KV 击穿表现为命中率骤降与首 token 延迟分位数尖峰同时出现；奖励池反压表现为生成批完成后样本排队时间上升、长尾队列深度异常增长；窗口过长表现为旧版本样本占比抬升并伴随奖励分数分布漂移。这些形态可以观测，但具体阈值论文卡未给出，因此任何“超阈值下调并发”的动作都需要先建立基线分布，再按分位数设定触发点。</p>\n<p>测量口径的完整性要求把三层指标对齐到同一时间轴：rollout 引擎的批发射节奏与 token 吞吐、奖励池的排队与打分延迟、训练侧消费的版本号分布。只有三层同轴，才能判断一次 SLO 恶化是生成侧拖尾、奖励侧反压还是同步窗口过长的传导。单看任何一层都会误判——例如首 token 延迟上升，可能是 KV 击穿，也可能是奖励池反压让 rollout 引擎的队列被占满。</p>\n<p>具体例子：面板上长尾队列深度抬升的同时 KV 命中率未降，说明拖尾不是预填问题，而是下游奖励池排队反压；此时扩容奖励池比下调生成并发更对症。反之，命中率下降而奖励池空闲，则是 KV 缓存容量不足，应调低并发或收紧 LRU 淘汰策略。这个判别逻辑把“监控 KV 命中率与长尾队列深度”从并列指标变成有方向的诊断树。阈值缺口是明确的局限：论文卡未给出失败模式的量化边界，落地时必须先用一段基线运行把各指标的分位数分布测出来，再设触发点，不能把机制描述当作实测结论。</p>\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-13\">十三 · 采样路径上的算子切分：从 GEMM 到采样头</h3>\n<p>ESSA 把 rollout 引擎与训练解耦之后，批量生成变成一条可独立排程的推理流水线。这条流水线上真正吃算力的算子只有三类：提示词预填阶段的 QKV 投影与注意力、逐 token 解码阶段的 GEMM 与注意力、以及末端的 logits 采样头。Blackwell 档位下，前两类走第五代 Tensor Core 的 tcgen05 路径，第三类则是带宽受限的小算子，三者对精度的敏感度并不相同，这正是量化方案必须在 NVFP4 与 FP8 之间做选择的物理根源。</p>\n<p>解码阶段每个 token 的计算可以写成一次矩阵-向量积：给定隐藏状态 <span>h</span> 与权重 <span>W</span>，输出 <span>y = W·h</span>。当批内并发为 <span>B</span> 时，它退化为 <span>B×1</span> 的瘦 GEMM，算术强度极低，性能由权重读取带宽决定而非浮点吞吐决定。设权重占 <span>M</span> 字节、HBM 有效带宽为 <span>BW</span>，则该步的下界时间为 <span>t ≥ M / BW</span>。把权重从 FP8 压到 NVFP4，<span>M</span> 近似减半，解码步时间随之减半——这是 NVFP4 在 ESSA 解码路径上的直接收益，也是它值得被认真评估的原因。但采样头不同：logits 经过 softmax 与温度缩放后进入分类采样，任何量化误差都会直接改变被采中的 token，进而改变整条轨迹的奖励分数。</p>\n<p>工程上的切分因此是：预填与解码的 GEMM 走低精度 Tensor Core 路径，采样头、softmax、温度与 top-p 掩码保持在 FP32 累加与 FP32 输出。以 ESSA 的长短混合提示词批次为例，主批按固定 token 预算推进时，预填段被前缀哈希命中大量跳过，真正跑满 Tensor Core 的是解码段；此时若把采样头也压到低精度，省下的带宽相对于整批解码微乎其微，却把采样稳定性这个独立监控项推到了风险区。代价判断很直接：采样头的 FP32 开销是每步一次 <span>V</span> 词表规模的读写，<span>V</span> 越大越贵，但它与解码 GEMM 的权重读取不在同一量级，保留高精度是划算的。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-14\">十四 · 数据类型逐层拆解：FP16/BF16/FP8/NVFP4 的位预算</h3>\n<p>四种格式的差别不只是位宽，而是指数位与尾数位的分配决定了它们各自能承受的动态范围与相对误差。FP16 是 1 符号 + 5 指数 + 10 尾数，BF16 是 1 + 8 + 7，FP8 在 Blackwell 上常用 E4M3（1 + 4 + 3）与 E5M2（1 + 5 + 2）两种，NVFP4 则是 1 + 2 + 1 的极窄格式，必须配块级缩放因子才能用。相对量化误差的量级可由尾数位数 <span>m</span> 估计为 <span>2^{-(m+1)}</span>：BF16 约 2⁻⁸，E4M3 约 2⁻⁴，NVFP4 在块内约 2⁻²。这个级数关系解释了为什么 NVFP4 不能裸用——单元素 4 bit 的相对误差已经大到足以摧毁 softmax 分布的尾部。</p>\n<p>NVFP4 的可用性来自两级缩放：一个 per-tensor 或 per-channel 的全局缩放因子，加上每 16 或 32 个元素一组的块级缩放因子（micro-block scaling）。反量化写成 <span>x ≈ s_g · s_b · q</span>，其中 <span>q</span> 是 4 bit 整数，<span>s_b</span> 是块缩放，<span>s_g</span> 是全局缩放。块越小，块内动态范围越窄，<span>s_b</span> 越能贴合局部数值分布，误差越小；代价是缩放因子本身的存储与读取开销上升。设块大小为 <span>k</span>，缩放因子的额外位宽为 <span>b_s</span>，则有效位宽为 <span>4 + b_s/k</span>。当 <span>k=16</span>、<span>b_s=8</span> 时有效位宽约 4.5 bit，相对 FP8 的 8 bit 仍是接近一半的带宽节省。</p>\n<p>对 ESSA 而言，格式选择必须按层分工而不是全局一刀切。注意力中的 QKV 投影与 MLP 的 up/gate 投影是数值最敏感的部分，激活中存在显著离群值，E4M3 的 4 位指数在这些通道上容易饱和；而 down 投影与输出投影的输入分布更集中，NVFP4 加块缩放可以承受。一个具体例子：若把整模型统一压到 NVFP4，采样稳定性监控项会先报警——不是吞吐掉了，而是同一提示词在不同 rollout 批次上产出的轨迹分布漂移，奖励分数方差变大，进而污染训练侧消费的样本。这正是论文卡把“量化在 NVFP4 与 FP8 间按采样稳定性选择”列为独立监控项而非一次性配置的原因。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-15\">十五 · 累加精度与误差传播：谁在放大谁</h3>\n<p>低精度乘法之后的累加路径决定了误差是被平均掉还是被放大。Tensor Core 的 MMA 指令在内部以更高精度累加：FP8 输入通常配 FP32 累加器，NVFP4 输入同样落到 FP32 累加。累加精度的作用可以用一个简化的误差模型说明。设一次点积有 <span>n</span> 项，每项量化误差为 <span>δ_i</span> 且近似独立同分布、均值零、标准差 <span>σ_q</span>，则和的误差标准差约为 <span>σ_q·√n</span>，而和的量级随 <span>n</span> 增长。因此相对误差约按 <span>1/√n</span> 收缩——这是低精度 GEMM 在长归约维度上仍可用的数学依据。</p>\n<div class=\"formula\">$$\\varepsilon_{\\text{rel}} \\approx \\frac{\\sigma_q\\sqrt{n}}{\\left|\\sum_{i=1}^{n} a_i b_i\\right|} \\sim \\frac{\\sigma_q}{\\sqrt{n}\\,\\bar{a}\\bar{b}}$$</div>\n<p>逐项解释：<span>σ_q</span> 是单元素量化噪声的标准差，由格式尾数位决定；<span>√n</span> 是独立误差求和的增长；分母是点积的真实量级。这个式子说明两件事：归约维度越长，低精度越安全；真实量级越小（即激活或权重接近零的通道），相对误差越危险。后者正是离群通道必须留在 FP8 或 BF16 的原因——它们的 <span>|Σ a_i b_i|</span> 小，误差不被稀释。</p>\n<p>误差还会跨层传播。在残差结构 <span>h_{l+1} = h_l + f_l(h_l)</span> 中，第 <span>l</span> 层的量化扰动 <span>δ_l</span> 会沿残差主干近乎无损地传到末端，而支路 <span>f_l</span> 的扰动则被后续层的雅可比放大或衰减。对 ESSA 的采样稳定性而言，关键不是单层误差绝对值，而是末端 logits 的误差是否改变了 top-p 集合的成员。一个可操作的工程判据是：在 rollout 引擎上线前，用同一批提示词分别在 FP8 与 NVFP4 下各跑一遍，比较被采样 token 的分布距离；若分布距离超过预设阈值，则该层回退到 FP8。这个比较本身要占 GPU 时间，属于量化选型的固定成本，应计入容量规划而非当作免费开关。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 如何改变代价结构</h3>\n<p>tcgen05 是 Blackwell 上第五代 Tensor Core 的指令族，它把 MMA 的累加器从寄存器文件搬到了张量内存（TMEM）。TMEM 是每个 SM 私有的、专供 Tensor Core 读写的一块片上存储，容量与寄存器文件分离。这一搬移改变了累加精度的代价：FP32 累加器不再挤占寄存器，寄存器压力下降，允许更大的 tile 与更深的流水。对 ESSA 的解码瘦 GEMM 来说，tile 变大意味着单次 MMA 覆盖更多并发请求的 token，批利用率提升；但解码阶段 <span>B</span> 受 SLO 与并发上限约束，tile 再大也填不满，收益主要体现在预填段与奖励模型打分这类大 GEMM 上。</p>\n<p>2-SM MMA 是另一项结构性变化：一条 MMA 指令可以跨两个 SM 协作完成，两个 SM 的 TMEM 与 Tensor Core 联合承担一个更大的矩阵块。设单 SM 的 MMA tile 为 <span>M×N×K</span>，2-SM 模式下等效 tile 在 <span>M</span> 或 <span>N</span> 方向翻倍，归约维度 <span>K</span> 的分片由两个 SM 各担一半再合并。这直接降低了每 SM 的权重读取次数——同一块权重被两个 SM 共享读取一次，HBM 流量按比例下降。对带宽受限的解码步，这是比提高浮点吞吐更实在的收益。代价是同步：两个 SM 必须在 MMA 边界对齐，任一 SM 的流水停顿会拖累另一方，因此对批内请求长度分布敏感——ESSA 把长尾样本放进低优先级队列，正是为了让主批的 token 预算稳定，避免 2-SM 协作因个别长请求而失步。</p>\n<p>把这些特性放回 ESSA 的三层结构：rollout 引擎的预填段吃 2-SM MMA 的带宽节省，解码段吃 NVFP4 的权重压缩，奖励模型与验证器的独立 serving 池吃 TMEM 带来的大 tile 效率。三者对精度的容忍度依次递减——预填段可以最激进，打分池次之，采样头最保守。硬件档位按 B200/B300/GB200 NVL72 分档时，NVL72 的机架级 NVLink 域让奖励池可以跨节点扩容而不牺牲通信，这使得“奖励池独立扩容”在 GB200 档位上才真正成立；在单机 B200 档位上，奖励池与 rollout 引擎争抢同一组 SM，队列解耦只能缓解排队而不能消除显存竞争。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-17\">十七 · 量化选型与 SLO 的耦合：把采样稳定性做成可监控项</h3>\n<p>ESSA 的推理侧把量化方案当作容量决策而非精度决策。理由在于：NVFP4 带来的解码步时间减半会直接抬高单位时间内的 rollout 样本产出，而样本产出是训练侧消费速率的输入；但若采样稳定性下降，样本质量受损，训练侧需要更多样本才能达到同等对齐效果，吞吐收益被抵消。设单位时间产出样本数为 <span>R</span>，单样本有效信息量为 <span>Q</span>，则有效产出为 <span>R·Q</span>。量化把 <span>R</span> 抬高、把 <span>Q</span> 压低，选型就是在这个乘积上取大。</p>\n<div class=\"formula\">$$\\text{有效产出} = R_{\\text{FP8}} \\cdot Q_{\\text{FP8}} \\;\\; \\text{vs} \\;\\; R_{\\text{NVFP4}} \\cdot Q_{\\text{NVFP4}}, \\quad R \\propto \\frac{1}{t_{\\text{decode}}}, \\;\\; t_{\\text{decode}} \\gtrsim \\frac{M}{BW}$$</div>\n<p>逐项解释：<span>R</span> 与解码步时间成反比，而解码步时间下界由权重字节数 <span>M</span> 与带宽 <span>BW</span> 之比给出；<span>Q</span> 无法从论文卡材料中取得实测值，只能通过采样分布距离与奖励分数方差间接监控。这意味着选型不能靠单次基准测试定死，而要在部署中持续观测。可操作的监控项包括：同一提示词跨批次的采样 token 分布距离、奖励分数的批内方差、以及长尾队列深度与 KV 命中率的联动——若 KV 缓存击穿导致预填尖峰，主批 token 预算被打乱，解码步的批利用率下降，此时 NVFP4 的带宽优势被预填开销吃掉，量化收益归零。</p>\n<p>具体例子：假设某批次主批按固定 token 预算推进，前缀哈希命中率高，解码段是瓶颈，NVFP4 让解码步时间减半，<span>R</span> 翻倍；但采样稳定性监控报警，奖励分数方差上升，训练侧不得不增大批次或延长短窗口 staleness 来补偿样本质量，吞吐收益被部分回吐。此时工程判断是分层量化：GEMM 走 NVFP4，采样头与 softmax 留 FP32，中间层按通道敏感度混用 FP8。这个组合的代价是 kernel 数量增加、调度复杂度上升，需要在 rollout 引擎的组批逻辑里为不同精度路径维护独立的 token 预算，否则混精度会破坏固定批大小的 SLO 承诺。论文卡材料未给出 NVFP4 采样稳定性的实测数据，因此上述判断只能作为机制层面的部署原则，任何吞吐数字都需标注未给出。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-18\">十八 · 失败模式与 kernel 级防线</h3>\n<p>量化路径上的失败模式有三类，且都与 ESSA 的解耦结构相互作用。第一类是缩放因子溢出：NVFP4 的块级缩放若在某批次上遇到极端激活，<span>s_b</span> 被推到格式上限，块内元素被截断，误差不再服从零均值假设，<span>1/√n</span> 的收缩失效。防线是在 kernel 内做块级钳位并记录钳位计数，计数超过阈值即触发该层回退到 FP8。第二类是累加器精度错配：若某条 kernel 路径误用 FP16 累加而非 FP32，长归约维度上的误差按 <span>√n</span> 增长而非收缩，症状是长提示词的 logits 尾部失真，表现为长尾样本的奖励分数系统性偏低——这会与 ESSA 的长尾低优先级队列叠加，让拖尾样本既慢又不准。第三类是 2-SM MMA 的失步：批内请求长度分布突变时，两个 SM 的流水对齐被破坏，有效吞吐下降而监控面板只显示批利用率正常，属于隐性代价。</p>\n<p>kernel 级防线的共同点是：把精度相关的异常做成可观测计数器，而不是靠离线基准测试一次性验证。这与 ESSA 把 NVFP4 采样稳定性列为独立监控项的思路一致——量化不是配置项，是运行时状态。对容量规划的含义是，rollout 引擎的并发上限不能只按 SLO 反馈调节，还要留出量化回退时的算力余量：一旦某层从 NVFP4 回退到 FP8，该层权重读取字节数翻倍，解码步时间随之上升，若并发上限不变则 SLO 被突破。因此在 B200/B300 档位上，量化选型应与并发上限联动配置，把回退路径的代价预先计入档位预算，而不是等监控报警后再临时下调并发——后者会在权重同步的短窗口内制造 staleness 与吞吐的双重抖动。</p>\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-19\">十九 · 显存账本的三个账户与可复算预算</h3>\n<p>在 Blackwell 上做 ESSA 的 rollout 服务，显存不是一块，而是三个互不相同、增长规律也不同的账户：权重（静态、按版本号整块换）、激活与工作区（随批内 token 数线性走）、KV cache（随并发会话数与上下文长度走，且被前缀共享改写）。三者混在一个预算里，就会出现“权重换版本时把 KV 挤掉、KV 击穿时预填尖峰把激活顶爆”的连锁失败。工程上先把账本写成可复算的式子，再谈分页与压缩。</p>\n<p>设模型参数量 $P$、每参数字节 $b_w$，权重账为 $M_w = P \\cdot b_w$。FP8 下 $b_w=1$，NVFP4 下权重为 4 bit 并带分组缩放因子，实际字节略高于 0.5，按块缩放开销估算。KV 账按层数 $L$、KV 头数 $H_{kv}$、头维 $d$、每元素字节 $b_{kv}$、并发 token 总数 $T_{kv}$ 计：</p>\n<div class=\"formula\">$$M_{kv} = 2 \\cdot L \\cdot H_{kv} \\cdot d \\cdot b_{kv} \\cdot T_{kv}$$</div>\n<p>系数 2 是 K 与 V 各一份。以 GQA 为例，$H_{kv}$ 远小于注意力头数，这一项直接决定单卡能挂多少并发 token。激活账则按批内最大 token 预算 $T_{b}$ 与每 token 峰值激活字节 $a$ 估：$M_{act} \\approx T_b \\cdot a$，$a$ 随算子融合与 tcgen05 的 TMEM 占用而变，TMEM 是片上资源，不占 HBM，但会限制单 SM 的并发 MMA 形态，从而间接压低可用的批大小。三账相加再留出通信缓冲与框架开销，就是单卡 HBM 预算。B200/B300 的 HBM3e 容量按档位不同，GB200 NVL72 则是把单机架内多卡的容量拼成统一池，容量数字以具体档位规格为准，此处不写死。可复算的做法是：先固定 $T_{kv}$ 与 $T_b$，反解出每卡可承载的并发会话数，再看权重换版本时的峰值是否越界。</p>\n<p>具体例子：一个 8 卡节点服务长短混合提示词，主批按固定 token 预算推进。若前缀命中率高，$T_{kv}$ 中大量 token 是共享前缀，KV 账增长慢；一旦缓存击穿，未命中的长提示集中预填，激活账瞬间抬高，同时新写入的 KV 又占容量，两个账户同时上行，这就是失败模式里“KV 缓存击穿导致预填尖峰”的显存侧成因。代价落在延迟上：预填尖峰期间 decode 批被挤压，首 token 时延抖动，吞吐下降。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-20\">二十 · 分页与前缀哈希：把 KV 从会话私有变成块共享</h3>\n<p>KV 分页的核心是把连续上下文切成固定大小的块（block），以块为分配单位，逻辑块到物理块的映射放在块表里。这样做的直接收益是消除会话间的外部碎片，长尾会话不必预留最大长度。ESSA 的前缀共享建立在此之上：对提示词前缀做哈希，命中则把逻辑块直接指向已存在的物理块，引用计数加一；未命中才预填并写缓存，淘汰走 LRU。命中判定的粒度必须是块对齐的，否则前缀末尾不满一块的部分要么重复预填、要么引入跨块复制。</p>\n<p>伪代码思路：查询时按块序列逐块比对哈希链，命中长度 $n_h$ 决定复用块数；预填只对 $n_h$ 之后的后缀执行，新块写入后登记哈希。引用计数归零的块进 LRU 队列，但被在途请求持有的块不能回收。代价是块表查询与哈希计算本身的开销，以及块粒度越细、块表越大带来的元数据显存；块粒度越粗、前缀命中越容易错位。工程判断是块大小与模型层结构、注意力实现对齐，让一次块读取对应一次规整的 MMA 载入。</p>\n<p>对 ESSA 而言，前缀共享不只是省算力，更是省显存时间：系统提示与少样本示例被大量请求共享，这部分 KV 只存一份，$T_{kv}$ 的有效增长被压平，单卡可挂并发会话数上升。反过来，命中率是显存预算的输入变量而非结果——预算表里必须把命中率当作参数扫描，而不是假设它恒定。监控面板把 KV 命中率与长尾队列深度并列，正是因为二者共同决定下一个批次的 $T_{kv}$ 与 $T_b$。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-21\">二十一 · 压缩与复用：量化 KV、跨请求复用、以及不能压的地方</h3>\n<p>KV 压缩有两条路：降低 $b_{kv}$，或降低 $T_{kv}$ 的有效长度。前者是 KV 量化，把 K/V 存成 FP8 甚至更低比特，配合分组缩放；后者是前缀共享、跨请求复用与选择性驱逐。Blackwell 上 FP8 KV 是稳妥档位，NVFP4 用于 KV 则要单独核验采样稳定性——材料明确说 NVFP4 下采样稳定性未给出实测，属待核验部署代价，因此不能把“4 bit KV 一定可行”写进预算。压缩的代价是数值误差进入注意力打分，长上下文下误差累积更明显，需要把采样稳定性作为独立监控项，而不是只看困惑度类的离线指标。</p>\n<p>复用还有一层是跨批次复用：同一提示词在多个 rollout 批次里重复出现时，前缀块可跨批次存活，只要引用计数与版本号对得上。这里与权重同步耦合——权重换版本后，旧版本产生的 KV 在数值上属于旧策略，是否可继续复用取决于 staleness 窗口的容忍度。材料给出的机制是版本号广播加短窗口，允许在途请求以旧权重完成；对应到 KV，就是旧版本块在新版本请求中不应被无条件命中，否则样本质量与权重版本脱钩。失败模式里“权重同步窗口过长引入旧版本样本”在显存侧的表现，正是旧 KV 块被过度复用。</p>\n<p>不能压的地方要写清楚：激活账里的峰值工作区、通信缓冲、以及 tcgen05 路径上的累加器与 TMEM 相关占用，压缩这些会直接伤到 MMA 形态与数值正确性。显存预算里应把它们列为硬预留，压缩只在前缀 KV 与权重上做文章。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-22\">二十二 · 卸载与带宽瓶颈：HBM3e 之外的那条路</h3>\n<p>卸载（offload）把冷 KV 块或非活跃会话的 KV 搬到主机内存甚至远端池，按需换回。收益是容量，代价是带宽。判断是否值得卸载，看一个比值：换回一次 KV 块的时间与重新预填该块的算力时间之比。若重新预填更便宜，就不要卸载，直接丢弃重算；若前缀很长、预填代价高，卸载才成立。这个判断必须按块做，不能按会话整体做。</p>\n<p>带宽瓶颈的位置要分清。单卡内，decode 阶段每生成一个 token 要把权重与 KV 都读一遍，算术强度低，HBM 带宽是主瓶颈；此时 KV 压缩直接换吞吐，因为读的字节少了。预填阶段算术强度高，算力是主瓶颈，前缀共享省的是算力而非带宽。跨卡，NVLink 5 承载张量并行与专家并行的激活通信，KV 若跨卡分片，decode 每步都要走一次链路，通信延迟进入关键路径；GB200 NVL72 机架内的统一池让 KV 分片不必落到主机内存，但跨机架仍要走网络。奖励模型与验证器作为独立 serving 池，与 rollout 引擎通过队列解耦，其显存账独立核算——这正是把奖励池从生成卡上拆出去的理由，避免打分与生成争抢同一份 HBM。</p>\n<p>具体例子：长尾队列里的会话上下文极长但到达稀疏，其 KV 常驻 HBM 会挤掉主批的活跃块。做法是把长尾会话的 KV 卸载到主机侧，主批按固定 token 预算推进；换回时若预填更便宜则直接重算。代价是长尾样本的时延变长，但因为它们在低优先级队列，不影响主批 SLO。监控长尾队列深度并按 SLO 反馈下调并发上限，就是在控制这条卸载路径的触发频率。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-23\">二十三 · 与调度、权重同步的耦合：预算表怎么随版本滚动</h3>\n<p>显存预算不是静态表，它随权重版本、批大小、命中率三者滚动。权重换版本时，$M_w$ 在切换瞬间可能双份存在（旧版本在途请求仍在跑），这是短窗口 staleness 的显存代价。预算必须预留一份权重影子空间，否则切换时要么阻塞在途请求、要么挤掉 KV 触发击穿。窗口长度决定影子空间存活时间，材料未给出 staleness 上界，因此这项预留只能按最坏在途请求数估，并把窗口长度作为可调参数纳入监控。</p>\n<p>批大小与 $T_b$ 的关系也要写进预算：主批按固定 token 预算组批，长尾进低优先级队列，批利用率下降时 GPU 空转，等于用显存换了个没跑满的批。此时正确动作是下调并发上限、回收低引用计数的 KV 块，而不是继续扩批把激活账顶高。奖励池排队反压生成时，rollout 引擎的队列深度上升，KV 驻留时间变长，$T_{kv}$ 实际占用高于稳态估计——这是“奖励池排队反压生成”在显存账本上的传导路径。</p>\n<p>可复算的预算流程：固定权重账与硬预留，按目标并发与命中率扫描解出 $T_{kv}$ 上限，再按主批 token 预算解出 $T_b$，两者相加不超过剩余 HBM；把权重影子空间与卸载缓冲作为独立项扣除；最后用长尾队列深度与 KV 命中率两个监控信号做闭环，超阈值下调并发。任何一项越界，优先砍并发而非砍精度——NVFP4 采样稳定性尚未实测，精度档位的选择不能由显存压力驱动。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-24\">二十四 · 前缀命中率跌下来之后：ESSA 显存账本的失效边界</h3>\n<p>ESSA 把 rollout 与训练解耦之后，KV 前缀共享成了显存账本里最脆弱的一项。前缀哈希命中时复用已写缓存，未命中才预填并写回；一旦命中率下滑，预填尖峰立刻吃掉预留的激活余量。按前缀哈希分桶的缓存容量可写成 <span class=\"formula\">$$C_{\\text{kv}}=\\sum_{p\\in\\mathcal{P}} H(p)\\cdot L_p \\cdot 2 \\cdot d_h \\cdot b$$</span>，其中 <span class=\"formula\">$$H(p)$$</span> 是前缀 <span class=\"formula\">$$p$$</span> 的命中次数、<span class=\"formula\">$$L_p$$</span> 为其 token 长度、<span class=\"formula\">$$d_h$$</span> 为每头维度、<span class=\"formula\">$$b$$</span> 为每元素字节数（NVFP4 与 FP8 不同）。命中率下降意味着 <span class=\"formula\">$$H(p)$$</span> 的分布从少数热点前缀摊薄到大量一次性前缀，同样的 token 预算下缓存条目数上升、单条复用次数下降，LRU 淘汰开始抖动，预填算力与写缓存的带宽同时上升。工程判断是：把命中率当作一级 SLO 信号，低于阈值时先收缩并发上限而不是扩缓存，否则缓存击穿会把预填尖峰转成整批空转。</p>\n<p>奖励池与验证器的独立 serving 解开了生成侧的显存争抢，但引入了新的反压路径。打分请求与生成请求分队列后，若奖励池排队深度超过生成批的推进节奏，队列反压会回传到 rollout 引擎，表现为主批 token 预算被迫缩小、批利用率下降。代价落在吞吐而非单请求延迟：主批按固定 token 预算推进时，长尾样本进低优先级队列，队列深度一旦超过阈值，低优先级样本被反复推迟，其 KV 缓存长期驻留，进一步压缩可用显存。监控面板应同时看长尾队列深度与 KV 驻留条目数，两者同升说明缓存被长尾占满，此时下调并发上限比扩大奖励池更有效。</p>\n<p>权重同步的短窗口是显存账本之外的另一类代价。版本号广播后允许在途请求以旧权重完成，窗口越长，旧版本样本占比越高，而 staleness 上界材料未给出，只能靠样本质量监控反推。窗口过短的代价是同步频繁打断在途批，批利用率下降；窗口过长的代价是旧版本样本混入训练消费，样本质量漂移。可复算的判据是：设窗口内旧版本请求占比为 <span class=\"formula\">$$\\rho$$</span>，则有效样本吞吐约为 <span class=\"formula\">$$(1-\\rho)\\cdot T_{\\text{batch}}$$</span>，<span class=\"formula\">$$\\rho$$</span> 上升时吞吐名义不变而有效样本下降。NVFP4 采样稳定性未给实测，量化档位选择缺少数据支撑，因此量化与 staleness 应作为两个独立监控项，不能互相替代。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>显存/带宽代价</th><th>可观测信号</th></tr></thead><tbody><tr><td>前缀命中率下滑</td><td>预填尖峰、缓存写带宽上升</td><td>命中率、预填排队深度</td></tr><tr><td>奖励池反压</td><td>主批预算收缩、长尾 KV 驻留</td><td>奖励队列深度、长尾队列深度</td></tr><tr><td>staleness 窗口过长</td><td>有效样本吞吐下降</td><td>旧版本请求占比 ρ</td></tr></tbody></table>\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-25\">二十五 · 连续批处理的组批单位：token 预算而非请求数</h3>\n<p>ESSA 的 rollout 引擎与训练进程解耦之后，调度器面对的第一个选择是“批以什么为单位”。按请求数组批在长短混合负载下会失效：一个 8K 提示词与一个 128 token 提示词同批，前者把整批的迭代步数拖到后者的数十倍，短请求早已生成完毕却仍占着槽位等长请求收尾，批利用率被最慢成员钉死。ESSA 的机制描述给出的答案是按固定 token 预算组主批——调度器维护一个每步可推进的 token 配额，从就绪队列里按前缀哈希与长度装箱，凑满预算即发车，而不是凑满请求数。</p>\n<p>形式化地，设第 <span>i</span> 个请求剩余生成长度为 <span>l_i</span>，批容量预算为 <span>B</span>，则组批是带约束的装箱：</p>\n<div class=\"formula\">$$\\max \\sum_{i\\in S} \\mathbb{1}\\left[\\sum_{i\\in S} l_i \\le B\\right],\\quad \\text{s.t. } \\mathrm{KV}_{\\mathrm{prefix}}(S)\\ \\text{命中率最大化}$$</div>\n<p>两个目标互相拉扯：token 预算约束保证单步解码的算力与显存带宽可预测，前缀命中率最大化则要求把共享同一系统提示的请求放进同一批，因为前缀 KV 只需预填一次。工程上的代价很直接——批越大，单步解码的 KV 读取带宽压力越大，decode 阶段是带宽受限而非算力受限；批越小，权重读取摊薄不足，吞吐掉。Blackwell 档位上这个平衡点随 NVFP4 与 FP8 的选择而移动：NVFP4 把权重与 KV 的字节数压下来，同样带宽预算下可容纳更大批，但采样稳定性成为独立监控项，不能只看吞吐。</p>\n<p>具体例子：一个对齐批次里 70% 请求共享同一段系统提示，30% 是长尾长提示。调度器先按前缀哈希把这 70% 装进主批，前缀 KV 一次预填、多次复用；剩下 30% 若强行塞入主批，会把主批的单步预算撑爆，于是进低优先级队列，等主批腾出预算再补位。这样主批的批利用率不被长尾拖垮，GPU 不空转。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-26\">二十六 · chunked prefill：把预填切片塞进解码步的缝隙</h3>\n<p>连续批处理解决了“批内成员不同步”的问题，但没有解决“预填与解码争抢同一批算力”的问题。一个长提示的预填是算力密集的，一次吃掉大量 FLOPs，若与解码请求同批，解码请求的 token 间延迟（ITL）会被预填尖峰拉出长尾。ESSA 材料里没有直接写 chunked prefill 这个词，但其“未命中的长提示走预填”“主批按固定 token 预算推进”的描述在机制上等价于把预填切成固定大小的 chunk，与解码步交错推进。</p>\n<p>伪代码思路：调度器每个迭代步先看预算，若队列头部是预填请求，就只取不超过 <span>C</span> 个 token 的 chunk 做前向，剩余部分留到下一步；若预算有余量，再拼上若干解码请求的单个 token。这样单步的计算量被钳在预算内，ITL 的方差被压下来。代价是预填请求的首 token 延迟（TTFT）变长——一个长提示被切成 <span>k</span> 个 chunk，就要跨 <span>k</span> 步才能出第一个 token，TTFT 近似正比于 chunk 数而非提示长度本身。</p>\n<div class=\"formula\">$$\\mathrm{TTFT}\\approx \\sum_{j=1}^{k}\\left(t_{\\mathrm{prefill}}(C)+t_{\\mathrm{decode}}(B_{\\mathrm{dec}})\\right),\\quad k=\\left\\lceil \\frac{L}{C}\\right\\rceil$$</div>\n<p>这就是时延与吞吐的正面取舍：chunk 越小，ITL 越稳、尾延迟越好，但 TTFT 越差、预填总算力里被解码步打断的固定开销占比越高；chunk 越大，TTFT 好，但解码请求被预填尖峰反复打断，尾延迟恶化。ESSA 的 KV 前缀共享在这里是减压阀——命中前缀的请求根本不需要预填，直接进解码批，只有未命中的长提示才需要走 chunked prefill，因此预填尖峰的频率被前缀命中率直接压低。监控面板上的 KV 命中率因此不只是显存指标，它是尾延迟的前置信号：命中率下滑意味着预填尖峰变密，ITL 长尾随之变厚。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-27\">二十七 · 优先级与抢占：长尾队列的深度就是 SLO 的刻度</h3>\n<p>ESSA 把长尾样本放进低优先级队列，这个设计的实质是把“拖尾”从批内问题转成队列问题。低优先级队列的成员不占主批预算，只在主批有余量时补位；一旦主批满载，它们就等着。于是系统的尾延迟不再由最慢样本决定，而由低优先级队列的深度与主批的排空速度共同决定。队列深度因此成为一个可观测的 SLO 刻度：深度持续上升说明到达率超过主批排空率，若不干预，低优先级请求的等待时间会线性增长。</p>\n<p>抢占是队列分级之外的第二道闸。当高优先级请求（例如交互式对齐任务的短提示）到达而主批已满，调度器需要决定是否驱逐批内某个低优先级成员、释放其 KV 槽位。驱逐的代价是重算：被驱逐请求已生成的 KV 若被丢弃，重新入队后要从头预填，除非其前缀仍在缓存中命中。ESSA 的 KV 策略是前缀哈希共享加 LRU 淘汰，这意味着被驱逐请求的前缀 KV 大概率还在，重算代价被压到只重算已生成的后缀部分。抢占的收益是尾延迟，代价是算力浪费与 KV 缓存的抖动。</p>\n<table class=\"mini\"><thead><tr><th>调度动作</th><th>直接代价</th><th>监控信号</th></tr></thead><tbody><tr><td>主批按 token 预算发车</td><td>批利用率受最慢成员影响</td><td>批利用率、单步预算占用</td></tr><tr><td>长尾进低优先级队列</td><td>低优先级请求等待时间上升</td><td>长尾队列深度</td></tr><tr><td>抢占驱逐低优先级成员</td><td>后缀重算、KV 缓存抖动</td><td>驱逐率、前缀命中率</td></tr><tr><td>下调并发上限</td><td>吞吐下降换取尾延迟收敛</td><td>staleness 窗口、队列深度</td></tr></tbody></table>\n<p>具体例子：监控面板观察到长尾队列深度越过阈值，同时 KV 命中率下滑，说明预填尖峰正在挤占解码预算。此时按 SLO 反馈下调并发上限——少收新请求，让主批先排空、让预填尖峰稀疏下来。这是用吞吐换尾延迟的显式动作，而不是等拖尾自然缓解。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-28\">二十八 · 分离式预填/解码与奖励池的独立扩容</h3>\n<p>ESSA 材料把奖励模型与验证器描述为独立 serving 池，与 rollout 引擎通过队列解耦，打分与下一批生成重叠。这在结构上就是分离式预填/解码思路的推广：生成与打分是两类形态不同的负载，生成是自回归解码、带宽受限、KV 常驻；奖励模型打分是一次前向、算力密集、无 KV 常驻。把两者塞进同一组 GPU 会互相争抢显存与算力——生成侧要留 KV 空间，打分侧要留激活与权重空间，任何一侧扩容都挤压另一侧。</p>\n<p>独立池的代价是跨池的数据搬运：生成的样本要序列化后送进奖励池队列，打分结果再回流到异步流水线。这条链路的带宽与延迟成为新的瓶颈点，尤其在 GB200 NVL72 这类机架级档位上，跨池流量走 NVLink 5 与机架内互联，池的放置位置直接影响搬运代价。若奖励池排队过长，会反压生成侧——生成完成的样本无处可送，rollout 引擎被迫降低发车速率，批利用率下降。这是材料列出的失败模式之一：奖励池排队反压生成。</p>\n<p>分离式预填/解码在 ESSA 语境下的对应物是“预填密集”与“解码密集”的资源分离：长提示预填可以放到专门的预填池，解码留在主池，两者按各自的最优批形态调度。代价同样是 KV 的跨池传递——预填产出的 KV 要搬给解码池，搬运量正比于前缀长度与层数，在 NVFP4 下字节数减半，搬运代价随之下降，但量化误差在跨池传递时不可再校正，采样稳定性监控必须覆盖这条路径。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-29\">二十九 · 权重同步的短窗口：staleness 是吞吐的抵押品</h3>\n<p>rollout 引擎与训练解耦后，权重版本切换成为一个调度事件而非训练事件。ESSA 的机制是版本号广播加短窗口：训练侧更新权重后广播新版本号，rollout 引擎在短窗口内允许在途请求以旧权重完成，窗口结束后新请求一律用新版本。这个设计的收益是吞吐——不必等所有在途请求排空才切换，避免了版本切换点的 GPU 空转；代价是样本质量，旧版本生成的样本混入训练批次，staleness 上界未给出，需单独监控。</p>\n<div class=\"formula\">$$\\text{吞吐增益}\\propto \\frac{W_{\\mathrm{switch}}}{W_{\\mathrm{switch}}+W_{\\mathrm{drain}}},\\quad \\text{样本偏差}\\propto \\mathbb{E}\\left[\\left\\|\\theta_{\\mathrm{old}}-\\theta_{\\mathrm{new}}\\right\\|\\right]\\cdot \\tau_{\\mathrm{stale}}$$</div>\n<p>窗口长度 <span>τ_stale</span> 是显式的旋钮：窗口越长，版本切换越平滑、吞吐越高，但旧版本样本占比越大，且旧新权重差异在窗口内可能持续扩大。窗口越短，样本新鲜度越好，但切换点附近在途请求被迫中断或重算，尾延迟出现尖峰。监控面板把 staleness 窗口与长尾队列深度并列，正是因为两者在版本切换点会耦合放大——切换时若队列本就很深，窗口内积压的旧版本请求更多。</p>\n<p>具体例子：一个对齐批次正在生成，训练侧完成一次权重更新并广播版本号。rollout 引擎不打断在途请求，主批继续以旧权重推进到收尾，同时新到达请求标记为新版本、在下一批发车时生效。奖励池在此期间持续打分，打分与下一批生成重叠。窗口结束后，监控比对旧版本样本占比与打分分布偏移，若偏移超出容忍则缩短下一轮窗口。NVFP4 采样稳定性在这里是叠加项：量化误差与权重 staleness 都会让样本分布偏移，两者需分开归因，否则无法判断偏移来自量化还是旧权重。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-30\">三十 · 尾延迟的压缩路径：三个可调点的联动</h3>\n<p>把上述机制串起来，ESSA 推理侧的尾延迟压缩不是单点优化，而是三个可调点的联动：批预算 <span>B</span>、chunk 大小 <span>C</span>、并发上限 <span>N</span>。调大 <span>B</span> 提升吞吐但拉长单步时间，调小 <span>C</span> 稳住 ITL 但恶化 TTFT，调低 <span>N</span> 收敛尾延迟但牺牲吞吐。三者没有独立最优，必须按 SLO 反馈联合调节，而反馈信号就是 KV 命中率、长尾队列深度、批利用率与 staleness 窗口这四个观测量。</p>\n<p>工程判断上，尾延迟的第一来源是预填尖峰而非解码本身，因此 KV 前缀共享的命中率是最高杠杆的变量：命中率每提升一档，预填请求数下降，chunked prefill 的切片压力与抢占频率同步下降，尾延迟的长尾被从源头削薄。第二来源是长尾队列的排空速度，它受主批预算与奖励池反压共同制约，因此奖励池的独立扩容不是可选项而是尾延迟治理的一部分。第三来源是版本切换点的 staleness 积压，窗口长度需与队列深度联动而非固定。</p>\n<p>需要明确的是，材料未给出任何吞吐与 SLO 收益数字，NVFP4 采样稳定性、长尾拖尾对批利用率的影响、staleness 上界均未量化。上述机制描述是可落地的调度骨架，不是实测结论；部署时这四个观测量必须先在目标档位（B200/B300/GB200 NVL72）上采集基线，再谈阈值。失败模式的优先级排序是：KV 缓存击穿导致预填尖峰最先表现为 ITL 长尾，奖励池反压其次表现为批利用率下滑，权重窗口过长最后表现为样本分布缓慢偏移——三者监控口径不同，不能合并成一个“健康度”指标。</p>\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-31\">三十一 · 切分拓扑：ESSA 推理侧的四条并行轴</h3>\n<p>ESSA 的推理侧被拆成 rollout 引擎、奖励/验证池、异步流水线三段，这三段各自对并行维度的偏好并不相同，因此不能用一个全局 TP 度把整机铺满。rollout 引擎承担自回归生成，单请求的 KV 随解码步线性增长，TP 切分直接决定每卡 KV 分片大小与每步 All-Reduce 的字节数；奖励模型与验证器是短序列、高并发的打分负载，更适合 DP 复制加小 TP；异步流水线的训练侧消费样本，PP 与 DP 的组合决定权重版本广播的扇出宽度。EP 在 ESSA 里的位置比较特殊：只有当奖励模型或验证器本身是 MoE 结构时才需要 EP，否则 EP 组可以并入 TP 组以复用同一批 NVLink 链路。</p>\n<p>切分的代价可以用一条守恒关系刻画。设单层注意力与 FFN 的计算量为 <span class=\"inline-math\">C</span>，参数量为 <span class=\"inline-math\">P</span>，TP 度为 <span class=\"inline-math\">t</span>，则每层每卡的通信量近似为</p>\n<div class=\"formula\">$$V_{\\mathrm{TP}} \\approx \\frac{2\\,(t-1)}{t}\\, b\\, s\\, h$$</div>\n<p>其中 <span class=\"inline-math\">b</span> 为微批、<span class=\"inline-math\">s</span> 为序列长度、<span class=\"inline-math\">h</span> 为隐藏维字节数。这条式子说明 TP 的通信开销随 <span class=\"inline-math\">t</span> 饱和而不随 <span class=\"inline-math\">t</span> 下降——把 TP 从 4 推到 8，每卡通信量只降一点，但每卡计算量减半，通信占比反而上升。ESSA 的工程判断因此是：rollout 引擎的 TP 度按单卡 KV 容量上限反推，而不是按算力反推；一旦 KV 分片能装下最长前缀，继续加 TP 只会把解码步的 All-Reduce 变成瓶颈。</p>\n<p>具体例子：一个长短混合的对齐批次，系统提示共享、单条长提示的前缀 KV 在 FP8 下占据可观显存。若 rollout 引擎用 TP=8 切分，每卡只持有八分之一前缀 KV，预填可以并行推进；但解码阶段每步都要在 8 卡间做两次 All-Reduce，单步延迟被通信主导。若改为 TP=4 加 DP=2，每卡 KV 分片翻倍但仍在容量内，解码步的 All-Reduce 参与者减半，单步延迟下降，代价是预填并行度下降、长提示预填变慢。这个取舍在 ESSA 里由长尾队列深度信号驱动：长尾队列深说明预填是瓶颈，倾向加 TP；长尾队列浅而解码步延迟高，倾向减 TP 加 DP。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-32\">三十二 · NVLink 5 与 NVSwitch：机架内带宽如何改变切分选择</h3>\n<p>GB200/GB300 NVL72 把 72 个 GPU 放进一个 NVLink 域，NVSwitch 让任意两卡之间的通信不经过 CPU 与 PCIe。对 ESSA 的直接含义是：TP 组、EP 组、甚至奖励池与 rollout 引擎之间的样本搬运，都可以落在同一个高带宽域内，切分的拓扑约束从“机内 8 卡”放宽到“机架 72 卡”。这带来两个具体机制变化。其一，TP 度可以跨节点边界设置而不触发跨域带宽悬崖，rollout 引擎可以把一个长前缀的 KV 分片铺到更多卡上，用带宽换容量。其二，奖励池与 rollout 引擎的队列解耦可以在同一 NVLink 域内实现零拷贝的样本句柄传递，打分结果不必落回主机内存再进训练侧。</p>\n<p>但 NVLink 域变大也放大了 All-to-All 的尾部。EP 的 All-to-All 在 MoE 奖励模型上表现为 token 路由，路由不均衡时最慢的那条链路决定整层延迟。设 EP 度为 <span class=\"inline-math\">e</span>，单层路由的 token 数为 <span class=\"inline-math\">n</span>，最热专家分到 <span class=\"inline-math\">\\(n_{\\max}\\)</span> 个 token，则 All-to-All 的有效带宽利用率为</p>\n<div class=\"formula\">$$\\eta_{\\mathrm{A2A}} = \\frac{n/e}{n_{\\max}}$$</div>\n<p>当 <span class=\"inline-math\">\\(n_{\\max}\\)</span> 显著大于均值时，即使 NVSwitch 提供充足带宽，EP 组仍在等最热专家。ESSA 的奖励池若走 EP，必须监控这个比值；若奖励模型是稠密结构，EP 组应直接退化为 TP 组，避免无谓的 All-to-All。</p>\n<p>代价面：NVLink 5 的高带宽并不消除功耗与散热约束。NVL72 机架的功耗预算固定，rollout 引擎把 TP 度推高会让更多卡在解码步同时参与 All-Reduce，活跃卡的功耗叠加抬升机架功耗，可能触发功耗封顶而降频。ESSA 的容量规划因此要把“解码步活跃卡数”作为一个独立变量，而不是只看总算力。具体例子：同一批请求在 TP=8 与 TP=4+DP=2 两种拓扑下总吞吐相近，但前者解码步有 8 卡同时活跃、后者只有 4 卡活跃，机架功耗曲线不同，后者在功耗封顶下更稳。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-33\">三十三 · All-Reduce 与 All-to-All 的瓶颈判据</h3>\n<p>ESSA 推理侧要区分两种集合通信的瓶颈形态。All-Reduce 出现在 TP 的每层前后，是延迟敏感型：解码步每步都要做，单次字节数小但频次高，瓶颈表现为单步延迟而非总带宽。All-to-All 出现在 EP 的 MoE 路由，是带宽敏感型：每层一次，字节数大，瓶颈表现为尾部链路。判据可以写成两个比值。对 All-Reduce，比较通信时间与计算时间：</p>\n<div class=\"formula\">$$\\rho_{\\mathrm{AR}} = \\frac{V_{\\mathrm{TP}} / B_{\\mathrm{NVLink}}}{C / F}$$</div>\n<p>当 <span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span> 接近或超过 1，TP 继续加度就是负收益。对 All-to-All，比较最热链路字节数与平均链路字节数，即上面的 <span class=\"inline-math\">\\(\\eta_{\\mathrm{A2A}}\\)</span> 的倒数。ESSA 的监控面板应把这两个比值与 KV 命中率、长尾队列深度并列，作为切分调整的输入信号。</p>\n<p>具体例子：rollout 引擎在解码阶段每步做两次 All-Reduce，若 <span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span> 已接近 1，此时增加 TP 度会让解码步延迟上升，长尾队列反而更长——因为主批推进变慢。反过来，若 <span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span> 远小于 1 而 KV 分片吃紧，加 TP 是合算的。这个判据把“通信什么时候成为瓶颈”从定性直觉变成可观测的比值，避免在 KV 容量与解码延迟之间盲目加度。</p>\n<p>还有一个容易被忽略的代价：All-Reduce 的频次与批大小耦合。ESSA 主批按固定 token 预算推进，批越大，单次 All-Reduce 字节数越大但频次不变，<span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span> 随批增大而上升。这意味着 ESSA 的固定批大小策略本身会推高 TP 通信占比，批大小与 TP 度必须联合调，不能各自独立设定。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-34\">三十四 · NIXL 传输：解耦之后样本怎么走</h3>\n<p>ESSA 把 rollout 引擎与训练侧解耦，样本与奖励分数要在两者之间搬运，权重版本号要反向广播。NIXL 在这条路径上的角色是提供点对点的异步传输抽象，让样本句柄、KV 前缀块、权重分片可以在 GPU 显存之间直接流动，而不必经过主机内存的多次拷贝。对 ESSA 而言，NIXL 解决的是三个具体搬运问题：rollout 产出的 token 序列与奖励分数进训练侧消费队列；权重更新后分片广播到 rollout 引擎的各 TP/DP 组；KV 前缀缓存的跨引擎共享（若多个 rollout 副本共享同一前缀池）。</p>\n<p>传输的代价面是队列深度与 staleness 窗口的耦合。权重广播走 NIXL 时，扇出宽度等于 rollout 引擎的 DP×TP 组数，广播完成时间随扇出线性增长。ESSA 的短窗口 staleness 容忍正是为这段广播时间设计的：在广播完成前，在途请求继续用旧版本权重完成，新请求等待新版本。设广播耗时为 <span class=\"inline-math\">\\(T_{\\mathrm{bcast}}\\)</span>，短窗口长度为 <span class=\"inline-math\">W</span>，则在途请求的旧版本比例近似为</p>\n<div class=\"formula\">$$f_{\\mathrm{stale}} \\approx \\min\\!\\left(1,\\ \\frac{T_{\\mathrm{bcast}}}{W}\\right)$$</div>\n<p>这个式子说明：广播越慢或窗口越短，旧版本样本比例越高。ESSA 材料未给出 <span class=\"inline-math\">W</span> 的上界，因此 <span class=\"inline-math\">\\(f_{\\mathrm{stale}}\\)</span> 只能作为监控项而非设定值。工程判断是：把 <span class=\"inline-math\">\\(T_{\\mathrm{bcast}}\\)</span> 压到窗口的一个小分数，靠 NIXL 的异步传输与扇出并行，而不是靠拉长窗口——拉长窗口会直接抬高旧版本样本比例，污染训练侧消费的样本质量。</p>\n<p>具体例子：权重版本切换时，rollout 引擎的多个 DP 副本同时收到广播，若广播串行扇出，最后一个副本收到新版本时前面的副本已经生成了若干批旧版本样本。这些样本进入奖励池打分后混入训练队列，训练侧按版本号消费时能看到版本标签，但样本质量差异未被量化。ESSA 的失败模式清单里“权重同步窗口过长引入旧版本样本”正对应这条路径，监控应记录每个样本的版本号与生成时刻，把 <span class=\"inline-math\">\\(f_{\\mathrm{stale}}\\)</span> 作为独立指标。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-35\">三十五 · 通信成为瓶颈的三个现场</h3>\n<p>第一个现场是 KV 缓存击穿导致的预填尖峰。前缀哈希未命中时，rollout 引擎要走预填，预填阶段的 TP 通信形态与解码阶段不同：预填是计算密集的长序列前向，All-Reduce 字节数随序列长度增长，<span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span> 在长提示上显著上升。若多个长提示同时未命中，预填尖峰会把 TP 组变成通信瓶颈，主批推进被拖慢，长尾队列深度上升。ESSA 的监控把 KV 命中率与长尾队列深度并列，正是为了捕捉这个耦合：命中率下降先于队列深度上升出现，是预填尖峰的先行信号。</p>\n<p>第二个现场是奖励池排队反压生成。奖励模型与验证器独立 serving，若打分吞吐低于生成吞吐，队列积压会反压 rollout 引擎，迫使引擎降并发。此时瓶颈不在 GPU 算力而在队列，通信（样本从 rollout 到奖励池的搬运）成为整条流水线的节拍器。ESSA 的独立扩容策略要求奖励池按打分吞吐扩容，而不是按生成吞吐扩容；扩容时若奖励池走 EP，还要检查 <span class=\"inline-math\">\\(\\eta_{\\mathrm{A2A}}\\)</span>，避免扩容后 All-to-All 尾部抵消扩容收益。</p>\n<p>第三个现场是权重同步窗口内的广播扇出。如上节所述，广播扇出宽度随 DP×TP 组数增长，NVL72 档位下扇出可以很大，广播时间成为版本切换的节拍。若窗口长度不足以覆盖广播时间，新请求等待、在途请求用旧权重，staleness 比例上升。工程判断是：把权重广播与样本搬运放在同一 NVLink 域内用 NIXL 并行推进，把广播时间压到窗口的小分数；若做不到，宁可缩短窗口、接受更多新请求等待，也不拉长窗口污染样本。</p>\n<p>三个现场的共同点是：通信瓶颈不表现为单卡算力不足，而表现为队列深度、命中率、staleness 比例这些系统级指标。ESSA 的容量规划因此不能只按算力反推卡数，必须把 NVLink 域内的集合通信比值、NIXL 广播扇出、奖励池队列深度作为独立约束。具体例子：一个 B200 档位部署，rollout 引擎 TP=4、DP=4，奖励池 DP=8 小 TP，权重广播扇出 16 路走 NIXL；若广播时间接近窗口，监控面板上 staleness 比例上升，此时应缩扇出（合并 DP 副本）或加窗口内的并行传输通道，而不是加卡。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-36\">三十六 · 切分与量化的联合约束</h3>\n<p>ESSA 的量化方案在 NVFP4 与 FP8 间按采样稳定性选择，这个选择与切分拓扑耦合。NVFP4 降低 KV 与权重的字节数，直接缩小 TP 分片的显存占用与 All-Reduce 的字节数，<span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span> 随字节数下降而下降——量化本身是缓解 TP 通信瓶颈的手段。但 NVFP4 下采样稳定性未给出实测，若采样分布偏移导致长尾样本比例上升，长尾队列深度会抵消量化带来的吞吐收益。ESSA 因此把采样稳定性作为独立监控项，与 KV 命中率、长尾队列深度并列。</p>\n<p>联合约束可以写成：切分度、量化精度、批大小三者不能独立设定。批大小推高 <span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span>，量化降低 <span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span>，切分度决定 <span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span> 的饱和点。ESSA 的工程判断是：先在 FP8 下确定切分拓扑与批大小，再把量化降到 NVFP4 观察采样稳定性与长尾队列深度；若稳定性可接受，NVFP4 释放的显存可以用于扩大 KV 前缀缓存或提高并发上限，而不是继续加 TP 度。这个顺序把量化当作容量释放手段而非算力提升手段，避免在通信瓶颈未解时盲目加度。</p>\n<p>具体例子：同一 NVL72 机架，FP8 下 rollout 引擎 TP=8 才能装下最长前缀 KV，解码步 <span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span> 偏高；切到 NVFP4 后 KV 字节减半，TP=4 即可装下，解码步 All-Reduce 参与者减半，<span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span> 下降，同时释放的显存用于扩大前缀缓存、提高 KV 命中率。这条路径的收益来自切分度下降与命中率上升，而不是来自 NVFP4 的算力；若 NVFP4 采样稳定性不可接受，则退回 FP8 并接受更高的 TP 度与更高的 <span class=\"inline-math\">\\(\\rho_{\\mathrm{AR}}\\)</span>，把长尾队列深度作为容量规划的硬约束。</p>\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-37\">三十七 · 精度塌陷：NVFP4 采样漂移的三种可观测形态</h3>\n<p>在 ESSA 的推理侧，量化档位不是全局常量，而是按采样稳定性在 NVFP4 与 FP8 之间逐层选择。精度塌陷之所以难诊断，是因为它不以报错形式出现，而是以分布偏移的形式渗入 rollout 样本。可观测形态有三类：其一，同一前缀在相同温度下多次采样，输出 token 的熵显著低于 FP8 参照，表现为“过早收敛到模板化回答”；其二，奖励分数分布左移且方差收缩，验证器对同一语义的判定出现系统性偏移；其三，长尾队列中的样本完成率下降，因为低概率 token 被量化噪声截断后触发重复解码。</p>\n<p>诊断的核心是建立一个与采样路径同构的影子指标。对每个批，记录 top-k logit 的量化前后相对误差：</p>\n<div class=\"formula\">$$\\delta_{\\mathrm{quant}}=\\frac{1}{B}\\sum_{b=1}^{B}\\frac{\\lVert \\ell^{\\mathrm{FP8}}_b-\\ell^{\\mathrm{NVFP4}}_b\\rVert_2}{\\lVert \\ell^{\\mathrm{FP8}}_b\\rVert_2}$$</div>\n<p>当 $\\delta_{\\mathrm{quant}}$ 在滑动窗口内越过基线，就把该层回退到 FP8 并重放当前批。代价是明确的：NVFP4 的吞吐优势来自更窄的权重与激活位宽，回退到 FP8 会抬高单 token 的显存带宽占用与 MMA 周期，直接压低批利用率；若不回退，塌陷样本会污染训练侧消费的奖励信号，且这种污染在异步流水线里被版本号掩盖，事后难以归因。具体例子：某对齐批次共享同一系统提示，前缀 KV 命中后进入解码，若 NVFP4 下采样熵在第三个解码步骤降，面板上表现为该前缀的“平均生成长度”突然缩短，而奖励池的通过率同步下滑——这两个信号必须联合触发，单看其一容易误判为提示词本身的问题。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-38\">三十八 · OOM 与 KV 击穿：预填尖峰的定位路径</h3>\n<p>ESSA 把 KV 前缀共享作为降低重复预填代价的主机制，按前缀哈希命中复用、未命中才预填并写缓存，配合 LRU 淘汰。OOM 的典型来源不是稳态显存占用，而是缓存击穿引发的预填尖峰：当一批长提示的前缀哈希集体未命中，rollout 引擎在短时间内需要为多个长序列同时分配 KV 页，与主批的解码页争抢同一显存池。此时监控面板上会出现三个同步特征——KV 命中率阶跃下跌、预填队列深度陡增、批利用率下降但 SM 占用率不降，因为预填本身是算力密集的。</p>\n<p>定位方法是把显存账目按页来源拆开，而不是只看总量：</p>\n<div class=\"formula\">$$M_{\\mathrm{peak}}=M_{\\mathrm{weight}}+M_{\\mathrm{decode}}+M_{\\mathrm{prefill}}+M_{\\mathrm{reward}}$$</div>\n<p>四项中只有 $M_{\\mathrm{prefill}}$ 是突发项，$M_{\\mathrm{reward}}$ 属于独立 serving 池、本不应与生成争抢，一旦它在 rollout 引擎的显存账目里出现，说明奖励池与生成被错误地部署在同一资源域，这是配置错误而非容量不足。工程判断上，先查前缀哈希的分布是否发生漂移（例如上游改了系统提示模板导致哈希全变），再查 LRU 淘汰阈值是否过紧使热前缀被逐出。具体例子：GB200 NVL72 档位下若把奖励池与 rollout 引擎混布，长提示预填尖峰与奖励打分排队会叠加成一次 OOM，而分池部署后同样的负载只表现为预填队列短暂加深，不触发分配失败。回滚动作是恢复上一版前缀模板并临时下调并发上限，让预填以更低并行度摊平尖峰。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-39\">三十九 · 批抖动与尾延迟：长尾队列深度的反馈控制</h3>\n<p>批抖动的本质是组批输入的长度分布不稳定，而 ESSA 的固定 token 预算组批把这种不稳定性转化为可观测的队列深度。主批按固定 token 预算推进，长尾样本进低优先级队列，避免拖尾阻塞主批造成 GPU 空转。抖动表现为相邻批的 token 预算填充率在阈值上下反复，尾延迟则表现为低优先级队列的等待时间分布出现长尾。二者是同一现象的两个切面：填充率下降说明主批被短样本占满而长样本积压，尾延迟抬升说明积压已越过可容忍窗口。</p>\n<p>反馈控制的结构是：以长尾队列深度与 KV 命中率作为调节信号，按 SLO 反馈下调并发上限。伪代码思路是——每个调度周期读取队列深度 $q$ 与命中率 $h$，若 $q$ 超过高水位且 $h$ 低于基线，则把并发上限乘以衰减因子；若 $q$ 回落且 $h$ 恢复，则缓慢回升，回升速率低于衰减速率以避免振荡。代价在于下调并发会直接降低批利用率与吞吐，因此这是一次显式的吞吐换尾延迟交易，必须记录每次调节的触发原因，否则面板上只剩一条无解释的并发曲线。具体例子：长短混合提示词批次中，若长尾队列深度持续上升而主批填充率仍高，说明预算分配偏向短样本，此时应提高长样本的预算权重而非简单降并发；反之若填充率与命中率同时下滑，则是前缀缓存失效，降并发只是止血。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-40\">四十 · 静默降级：奖励池反压与 staleness 窗口</h3>\n<p>静默降级是 ESSA 推理侧最危险的失败模式，因为它不产生错误码，只产生“看起来正常但质量下滑”的样本。两个来源：奖励池排队反压生成，以及权重同步窗口过长引入旧版本样本。前者表现为打分与下一批生成的重叠被打破——奖励池队列变长后，rollout 引擎的完成队列被反压，批利用率表面维持但实际在途请求变多，尾延迟悄悄抬升；后者表现为版本号广播后，短窗口内旧权重仍在为在途请求服务，若窗口长度超过设计上界，训练侧消费的样本会混入旧策略分布。</p>\n<p>监控 staleness 需要把版本号与样本绑定，而不是只看窗口计时：</p>\n<div class=\"formula\">$$s=\\frac{1}{N}\\sum_{i=1}^{N}\\left(v_{\\mathrm{train}}-v_i\\right)$$</div>\n<p>其中 $v_i$ 是第 $i$ 个样本生成时使用的权重版本。$s$ 的滑动均值与方差必须与奖励分数分布联合观察：若 $s$ 上升而奖励分布方差收缩，说明旧版本样本正在系统性地拉低多样性。工程判断上，staleness 上界未给出量化值，因此不能把它当作已知常量配置，而应作为独立监控项并在越界时缩短窗口、强制在途请求重放。代价是缩短窗口会牺牲吞吐，因为部分在途请求被丢弃重算，批利用率出现瞬时凹陷。具体例子：权重同步后若面板显示 KV 命中率正常、批利用率正常，但奖励池通过率缓慢下滑且 $s$ 单调上升，这就是典型的静默降级，回滚动作是把窗口缩到最小并标记该批样本为待复核，而不是等 SLO 报警。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-41\">四十一 · 监控面板与回滚顺序</h3>\n<p>面板的最小充分集是四项：KV 命中率、长尾队列深度、批利用率、staleness 均值。四项必须同屏且带同一时间轴，因为失败模式几乎都以组合形式出现，单项越界不足以定位。精度塌陷看命中率正常但奖励分布偏移；OOM 看命中率阶跃与预填队列同步；批抖动看队列深度与填充率的反相；静默降级看 staleness 与奖励方差的同向。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要信号</th><th>伴随信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷</td><td>量化相对误差越界</td><td>采样熵下降、奖励左移</td><td>该层回退 FP8 并重放当前批</td></tr><tr><td>OOM</td><td>KV 命中率阶跃下跌</td><td>预填队列陡增、SM 占用不降</td><td>恢复前缀模板、下调并发</td></tr><tr><td>批抖动</td><td>长尾队列深度越界</td><td>填充率与命中率反相</td><td>调预算权重，必要时降并发</td></tr><tr><td>静默降级</td><td>staleness 均值上升</td><td>奖励方差收缩</td><td>缩短窗口、标记样本复核</td></tr></tbody></table>\n<p>回滚顺序的原则是先止血再归因：精度与 OOM 属于资源域问题，先回退量化档位或恢复前缀模板；批抖动与静默降级属于调度域问题，先调并发与窗口再查根因。每次回滚必须记录触发时的四项面板读数，否则同一失败模式会在下一次权重同步后复现而无人识别。具体例子：若一次回滚只记录了“下调并发”，事后无法区分是长尾拖尾还是奖励池反压所致，下一次同类信号出现时仍会走同一条错误路径。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-42\">四十二 · 诊断的边界：未量化的阈值与可核验项</h3>\n<p>必须明确的是，材料未给出 NVFP4 采样稳定性的实测、长尾拖尾对批利用率影响的量化、以及 staleness 上界的数值。这意味着上述所有阈值在部署时都是待标定项，而非可直接套用的常量。可核验的机制点只有三条：rollout 引擎与训练解耦后批量生成按固定批大小与 SLO 独立调度；奖励模型与验证器独立 serving 池与生成重叠；KV 前缀共享降低重复预填。任何把机制描述当作实测收益的表述都应被拒绝。</p>\n<p>因此诊断系统的设计应把“阈值来源”本身作为元数据：每个告警携带阈值是标定得来还是默认占位，回滚决策据此区分可信与试探。对 Blackwell 档位，量化方案在 NVFP4 与 FP8 间的选择必须与采样稳定性监控绑定，而不是按档位一次性写死；B200/B300/GB200 NVL72 的并行拓扑差异会改变预填尖峰的形态，同一阈值跨档位迁移前需重新标定。最终落在一条工程判断上：ESSA 推理侧的失败模式诊断，本质是把解耦带来的每一个独立容量域（rollout、奖励池、KV 缓存、权重版本）都配上独立的可观测项与独立的回滚动作，任何跨域合并监控的做法都会把静默降级藏进平均值里。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-43\">四十三 · 失效链的耦合点：从KV击穿到staleness失控</h3>\n<p>ESSA把rollout引擎与训练解耦后，失败不再表现为单点崩溃，而是沿三条耦合链传导。第一条是KV前缀缓存击穿：前缀哈希命中率骤降时，未命中请求全部走预填，预填算力与显存瞬时抬升，主批的固定token预算被预填挤占，长尾队列深度随之上涨。设主批token预算为<code>B</code>、命中率为<code>h</code>、单请求平均预填代价为<code>c</code>，则预填开销近似为<div class=\"formula\">$$C_{\\mathrm{prefill}} \\approx (1-h)\\cdot N\\cdot c$$</div>其中<code>N</code>为本轮请求数。命中率从稳态跌落时，<code>C_prefill</code>线性放大，直接吃掉本可用于解码的SM与HBM带宽，表现为批利用率下降而GPU功耗不降——空转的典型信号。第二条是奖励池反压：打分队列深度超过池容量后，rollout引擎的完成队列被阻塞，生成侧并发被迫下调，形成吞吐自抑制。第三条是权重同步窗口：版本号广播后短窗口内旧权重在途请求继续完成，窗口越长，旧版本样本占比越高，训练侧消费到混合版本样本，样本质量监控若只看奖励均值会掩盖分布漂移。</p>\n<p>诊断顺序应按代价从低到高排：先看KV命中率与长尾队列深度这两个无侵入指标，二者同时恶化即判定为预填尖峰而非请求分布变化；再看奖励池队列深度与rollout完成队列的背压比，若背压比持续大于1则奖励池需独立扩容而非调rollout并发；最后才查staleness窗口内的版本分布，用版本号打标统计旧版本样本占比<div class=\"formula\">$$r_{\\mathrm{stale}} = \\frac{N_{\\mathrm{old}}}{N_{\\mathrm{total}}}$$</div>该比值超过窗口设计预期即说明窗口过长或权重广播延迟。回滚粒度对应三层：KV层回滚到上一版前缀缓存快照并临时关闭共享、奖励池回滚到扩容前配置并恢复耦合serving、权重层缩短窗口并强制在途请求重放。下表给出失败模式与首要观测量的对应，阈值材料未给出，需按SLO反馈标定。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要观测量</th><th>系统代价</th><th>回滚动作</th></tr></thead><tbody><tr><td>KV缓存击穿</td><td>前缀命中率、预填队列深度</td><td>预填算力与显存尖峰，批利用率下降</td><td>关闭前缀共享，回退缓存快照</td></tr><tr><td>奖励池反压</td><td>打分队列深度、背压比</td><td>生成并发被压制，吞吐自抑制</td><td>奖励池独立扩容，恢复分队列</td></tr><tr><td>staleness失控</td><td>旧版本样本占比、奖励分布漂移</td><td>样本质量下降，训练侧消费混合版本</td><td>缩短窗口，在途请求重放</td></tr><tr><td>NVFP4采样塌陷</td><td>采样稳定性指标、奖励方差</td><td>需回退FP8，吞吐与显存代价上升</td><td>量化档位切回FP8</td></tr></tbody></table>\n<p>静默降级最隐蔽的一条是NVFP4采样稳定性：量化档位按采样稳定性选择，但材料未给出实测，采样分布尾部若被量化截断，奖励分数会整体偏移而不触发任何队列告警，表现为奖励均值平稳但训练侧梯度信号变弱。工程判断是：把采样稳定性与奖励方差作为与KV命中率并列的一级监控项，任一漂移即触发量化档位回退到FP8，接受吞吐与显存代价换取分布可信；同时staleness窗口必须与版本号绑定而非与时间绑定，窗口长度以旧版本样本占比<code>r_stale</code>为约束反推，而非拍定秒数。长尾队列深度阈值同样应由批利用率反推：当长尾样本占用主批token预算的比例超过可接受空转代价时下调并发上限，这一反馈环是ESSA解耦架构里唯一能同时约束吞吐与SLO的调节点。</p>\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-44\">四十四 · 口径先于数字：ESSA 推理侧的可核验边界</h3>\n<p>读 ESSA 的推理性能数字，第一件事不是看吞吐，而是确认这个数字挂在哪个口径上。论文卡材料对推理侧的描述是机制级的：rollout 引擎与训练解耦、批量生成按固定 token 预算组主批、长尾样本进低优先级队列、奖励模型与验证器独立 serving、KV 前缀哈希共享、权重同步用版本号加短窗口。材料明确未给出数据集、基线数字与硬件实测。这意味着任何“ESSA 比 PPO 式 rollout 快多少”的表述都必须标注为未给出，而不是把机制描述当成实测结论。工程读者需要建立的口径清单是：模型与精度档位（NVFP4 还是 FP8）、硬件档位（B200、B300、GB200 NVL72）、batch 的定义（请求数还是 token 预算）、并发上限的来源（SLO 反馈还是固定值）、指标是 TTFT、TPOT、吞吐、显存还是功耗。缺任何一项，数字就不可比。</p>\n<p>一个具体机制是组批口径：主批按固定 token 预算推进，而不是按固定请求数。固定 token 预算下，长短混合提示词的批内 token 数稳定，decode 阶段的每步计算量可预测；固定请求数则会让长提示词把批撑爆，短提示词让批欠载。代价直接落在批利用率上：token 预算口径下批利用率可监控，请求数口径下批利用率随长度分布漂移，GPU 空转与显存峰值都不可控。举例：一个含系统提示、长文档与短问答的混合批次，按 token 预算组批时短问答填充主批、长文档进低优先级队列；按请求数组批时同一批里长文档独占显存，短问答的 decode 步被拖慢，TTFT 分布出现双峰。</p>\n<div class=\"formula\">$$\\text{批利用率}=\\frac{\\sum_{i\\in\\text{batch}} \\text{tokens}_i}{\\text{batch\\_slots}\\times \\text{max\\_tokens\\_per\\_slot}}$$</div>\n<p>这个比值在 ESSA 的监控面板里与 KV 命中率、长尾队列深度并列。材料未给出阈值，因此工程上只能把它作为相对信号：同一硬件档位、同一模型精度下横向比较才有意义，跨档位比较需要重新标定。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-45\">四十五 · 硬件档位与量化：NVFP4 采样稳定性是独立监控项</h3>\n<p>ESSA 的硬件档位按 B200、B300、GB200 NVL72 分档，并行拓扑与量化方案随档位选择。材料未给出切分细节，但给出了选择逻辑：量化在 NVFP4 与 FP8 之间按采样稳定性选择，采样稳定性作为独立监控项。这句话的工程含义是，NVFP4 的吞吐优势不能无条件兑现——ES 的采样过程对数值扰动敏感，因为 $$\\mathcal{L}_{\\mathrm{ES}}=\\mathbb{E}_{\\epsilon\\sim\\mathcal{N}(0,\\sigma^{2})}\\left[F(\\theta+\\epsilon)\\,\\epsilon\\right]$$ 依赖扰动方向上的适应度反馈，采样分布若因量化误差偏移，扰动方向的有效性下降，样本质量而非吞吐成为瓶颈。因此 NVFP4 的收益必须与采样稳定性指标一起读：同一档位下 NVFP4 吞吐更高，但若稳定性监控项恶化，有效样本率下降，端到端对齐效率未必提升。</p>\n<p>代价落在显存与功耗两侧。NVFP4 降低权重与 KV 的位宽，显存占用下降，允许更大 batch 或更长 KV；但采样稳定性未实测，材料未给出 NVFP4 下的稳定性数据，因此不能把“NVFP4 提升吞吐”写成结论。GB200 NVL72 档位的差异在于 NVLink 域更大，奖励池与 rollout 引擎跨节点部署时通信代价结构不同，材料未给出切分细节，只能定性说档位选择影响奖励池独立扩容的拓扑。举例：B200 单机档位下奖励池与 rollout 引擎同机部署，队列解耦但共享显存；GB200 NVL72 档位下奖励池可独立占节点，显存不再与生成争抢，但打分请求跨 NVLink 传输，TTFT 口径需区分本地与跨节点。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>材料给出的状态</th><th>读数约束</th></tr></thead><tbody><tr><td>模型与精度</td><td>NVFP4/FP8 按采样稳定性选择</td><td>NVFP4 稳定性未实测，吞吐数字需附稳定性监控</td></tr><tr><td>硬件档位</td><td>B200/B300/GB200 NVL72 分档</td><td>切分细节未给出，跨档位不可直接比</td></tr><tr><td>batch 定义</td><td>固定 token 预算组主批</td><td>与请求数组批的口径不可混用</td></tr><tr><td>并发上限</td><td>按 SLO 反馈调节</td><td>阈值未给出，只能相对比较</td></tr><tr><td>指标</td><td>TTFT/TPOT/吞吐/显存/功耗</td><td>材料未给出实测值</td></tr></tbody></table>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-46\">四十六 · 指标怎么读：TTFT、TPOT 与吞吐的分母</h3>\n<p>ESSA 的 rollout 引擎按请求长度分布组批，KV 前缀哈希命中复用，未命中才预填。这决定了 TTFT 的口径必须拆成两段：命中前缀的请求 TTFT 主要是 decode 首步与队列等待，未命中的请求 TTFT 含预填。把两者混在一个平均值里，KV 命中率的变化会被平均掉。工程读法是分别看命中与未命中的 TTFT 分布，再看命中率本身。代价在预填尖峰：KV 缓存击穿时未命中请求集中预填，TTFT 尾部拉长，主批被预填抢占算力，TPOT 同步恶化。举例：系统提示统一的长文档问答，前缀哈希命中率高时 TTFT 集中在短尾；缓存淘汰策略触发后一批请求同时未命中，预填尖峰使 TTFT 尾部抬升，此时吞吐数字若只看总 token 数会掩盖 SLO 违约。</p>\n<p>TPOT 的口径取决于 decode 阶段的批内 token 数与 KV 读取带宽。固定 token 预算组批使 TPOT 可预测，但长尾队列的低优先级样本若被插入主批，TPOT 方差上升。吞吐的分母必须写清楚：是生成 token 每秒、打分请求每秒，还是端到端对齐样本每秒。ESSA 的奖励池与生成重叠，打分吞吐与生成吞吐是两个独立口径，把两者相加得到的“总吞吐”在 SLO 上不可比，因为打分请求的延迟约束与生成请求不同。功耗口径同理：NVFP4 下单位 token 能耗下降的前提是采样稳定性不迫使重采样，材料未给出该数据。</p>\n<div class=\"formula\">$$\\text{SLO 违约率}=\\frac{\\#\\{\\text{req}: \\text{TTFT}&gt;T_{\\text{ttft}}\\ \\lor\\ \\text{TPOT}&gt;T_{\\text{tpot}}\\}}{\\#\\text{req}}$$</div>\n<p>这个违约率是并发上限调节的反馈信号。材料说长尾队列深度超阈值则下调并发上限，阈值未给出，因此工程上只能把违约率与队列深度一起看：队列深度上升而违约率未升，说明低优先级队列在吸收拖尾；两者同升则说明主批已被拖尾侵入。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-47\">四十七 · 哪些提升不可比：解耦收益与耦合基线的错位</h3>\n<p>ESSA 最容易被误读的“提升”是解耦带来的吞吐收益。传统 PPO 式 rollout 与训练强耦合，批量生成受梯度步节奏牵制；ESSA 解耦后批量生成按固定批大小与 SLO 独立调度。若基线是耦合式 rollout，那么 ESSA 的吞吐提升里混着两个来源：调度解耦带来的批利用率提升，以及 ES 本身不需要 rollout 与训练同步带来的采样开销下降。这两者在数字上不可分离，材料未给出消融，因此不能把解耦收益单独归因。可比的口径是同一硬件档位、同一模型精度、同一请求长度分布下，耦合与解耦两种调度形态的批利用率与 TTFT 分布对比；材料未给出该对比。</p>\n<p>第二个不可比点是奖励池独立 serving。材料说奖励模型与验证器作为独立 serving 池，与 rollout 引擎通过队列解耦，打分与下一批生成重叠。若基线是奖励模型与生成共享显存，那么独立池的收益体现在生成 batch 可更大、打分不抢显存；但独立池引入跨池队列延迟，打分请求的 TTFT 口径与生成不同。把“打分与生成重叠”读成“端到端延迟下降”是错的：重叠提升的是批利用率与 GPU 占用率，端到端对齐样本的产出节奏取决于训练侧按版本号消费的速度。举例：奖励池独立扩容后生成 batch 增大，生成吞吐上升，但打分队列积压时训练侧消费被反压，端到端样本产出未必同比例上升。</p>\n<p>第三个不可比点是权重同步短窗口。材料说权重同步采用版本号广播加短窗口，允许在途请求以旧权重完成以换吞吐，staleness 上界未给出。这意味着吞吐数字里包含旧版本样本，样本质量口径与新鲜权重口径不同。若把含 staleness 的吞吐与无 staleness 的吞吐直接比，提升不可比；正确读法是同时报告 staleness 窗口长度与旧版本样本占比，材料未给出这两个量，因此该收益只能定性描述为“以样本新鲜度换吞吐”。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-48\">四十八 · 失败模式对应的口径缺口</h3>\n<p>材料列出的失败模式直接映射到口径缺口。KV 缓存击穿导致预填尖峰：口径缺口是 KV 命中率与未命中 TTFT 未分列，读数是 TTFT 尾部而非均值。奖励池排队反压生成：口径缺口是打分队列深度与生成队列深度未分列，读数是端到端样本产出节奏而非生成吞吐。权重同步窗口过长引入旧版本样本：口径缺口是 staleness 窗口与旧版本样本占比未给出，读数是样本质量监控项而非吞吐。长尾拖尾使批利用率下降：口径缺口是长尾队列深度阈值未给出，读数是批利用率与违约率的联合走势。</p>\n<p>工程判断落在监控面板的字段设计上：KV 命中率、批利用率、长尾队列深度、staleness 窗口、NVFP4 采样稳定性，这五项是 ESSA 推理侧可独立监控的量，材料均未给出阈值与实测。因此部署时的第一步不是复现吞吐数字，而是把这五项接到同一时间轴上，观察它们与 TTFT/TPOT 分布的联动。举例：长尾队列深度上升时若 KV 命中率同步下降，说明长尾样本多为未命中前缀，预填代价与拖尾叠加，此时下调并发上限只能缓解违约率，不能恢复批利用率；需要先调前缀共享策略或缓存淘汰策略。这个判断不需要实验数字，只需要机制层面的因果链，而材料给出的正是这条链。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-49\">四十九 · 边界不在算法在口径：ESSA 推理收益的可比性判据</h3>\n<p>ESSA 的推理侧收益全部来自“解耦”这一结构性动作，因此它的失效条件也几乎全部落在耦合点上，而非 ES 公式本身。第一个耦合点是权重版本：短窗口 staleness 让在途请求以旧权重完成，吞吐上去了，但样本分布被拉成两个版本混合，奖励分数的可比性下降。设窗口长度为 <span class=\"formula\">$$W$$</span>、请求平均在途时间为 <span class=\"formula\">$$\\bar{t}$$</span>，则旧版本样本占比近似为 <span class=\"formula\">$$\\rho \\approx \\min(1, W/\\bar{t})$$</span>；<span class=\"formula\">$$\\rho$$</span> 没有实测上界，只能靠监控面板观察分数漂移。第二个耦合点是 KV 前缀共享：命中率一旦被长尾请求的独特前缀稀释，预填尖峰就会反压组批，主批的固定 token 预算被击穿，GPU 空转重新出现。第三个是奖励池：独立 serving 池解耦了显存争抢，却把排队转移到队列上，打分延迟超过生成节奏时，重叠失效、批利用率回落。</p>\n<p>因此读 ESSA 的数字必须先对齐四元组：硬件档位（B200/B300/GB200 NVL72）、量化口径（NVFP4 还是 FP8）、组批口径（固定 token 预算还是固定请求数）、并发上限来源（SLO 反馈还是静态设定）。任何一项不同，TTFT/TPOT 与吞吐都不可直接比较。尤其 NVFP4 采样稳定性未给出实测，NVFP4 与 FP8 两档的吞吐差异不能当作纯量化收益读，因为采样稳定性本身会改变有效批构成。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发信号</th><th>系统代价</th></tr></thead><tbody><tr><td>KV 缓存击穿</td><td>前缀命中率骤降、预填排队</td><td>预填算力与显存尖峰，主批推迟</td></tr><tr><td>奖励池反压</td><td>打分队列深度持续上升</td><td>生成与打分重叠失效，批利用率下降</td></tr><tr><td>staleness 过长</td><td>旧版本样本占比升高</td><td>样本质量不可比，需重跑或丢弃</td></tr></tbody></table>\n<p>工程判断上，ESSA 的容量规划应把长尾队列深度与 KV 命中率当作一等 SLO 指标，而不是事后诊断项；拖尾超阈值即下调并发上限，是以吞吐换稳定性的显式取舍。论文卡未给出数据集、基线数字与硬件实测，任何“解耦带来吞吐提升”的表述都只能作为机制描述，不能作为可比结论引用。</p>\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-50\">五十 · 迁移到非对齐任务：ES 采样器的可替换边界</h3>\n<p>ESSA 的推理骨架建立在一条假设上：批量生成可以脱离梯度步节奏，按固定 token 预算独立推进。这条假设在奖励信号稀疏、验证器可程序化判定的任务上成立；一旦迁到奖励不可分解或判定代价极高的领域，骨架本身不动，但奖励池的容量模型必须重算。具体机制是：rollout 引擎只负责产出候选样本，奖励池负责打分，两者通过队列解耦——迁移时真正要改的是队列的背压策略，而非生成侧组批逻辑。伪代码层面，打分延迟 <span>τ<sub>score</sub></span> 与生成吞吐 <span>R<sub>gen</sub></span> 的关系决定了奖励池副本数 <span>N<sub>rm</sub></span>：</p>\n<div class=\"formula\">$$N_{\\mathrm{rm}} \\ge \\left\\lceil \\frac{R_{\\mathrm{gen}} \\cdot \\tau_{\\mathrm{score}}}{B_{\\mathrm{rm}}} \\right\\rceil$$</div>\n<p>其中 <span>B<sub>rm</sub></span> 是单个奖励模型副本的批容量。迁到代码生成这类验证器需要实际执行单元测试的领域，<span>τ<sub>score</sub></span> 从毫秒级跳到秒级，<span>N<sub>rm</sub></span> 会成倍膨胀，奖励池从“与生成重叠的旁路”变成“吞吐瓶颈”。此时若仍按原比例扩容，显存会被奖励模型副本挤占，KV 前缀缓存的 LRU 淘汰空间被压缩，命中率下滑反过来推高预填尖峰。工程判断是：迁移前先测 <span>τ<sub>score</sub></span> 的分布尾部，若 P99 超过生成单批时延的一个数量级，就应把验证器改成两级——轻量启发式过滤在前，重验证在后，而不是线性堆副本。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-51\">五十一 · 换模型：前缀共享与权重同步的耦合变化</h3>\n<p>KV 前缀共享按前缀哈希命中复用，其收益取决于系统提示与少样本示例在请求间的重复度。迁到指令微调差异大的模型族时，tokenizer 与 chat template 改变会直接改变前缀哈希的分布：同一段系统提示在不同模板下 token 序列不同，缓存无法跨模型复用，命中率按模板切换频率衰减。代价体现在预填算力上——未命中请求要走完整预填，长提示下预填占单请求 FLOPs 的比例上升，批利用率被预填尖峰打断。迁移时必须把前缀哈希的键从“原始文本”改为“模板渲染后的 token 序列加模型版本号”，否则跨版本缓存会命中错误内容。</p>\n<p>权重同步的短窗口 staleness 在换模型时暴露另一个问题：不同参数规模下，一次权重广播的传播时延不同。GB200 NVL72 档位内广播走 NVLink 域，跨档位则要经更慢的链路，短窗口长度若按小模型标定，迁到大模型会出现窗口内旧版本请求占比过高。可用事实明确 staleness 上界未给出，因此迁移判断只能定性：窗口长度应以“在途请求完成率的拐点”为界，监控面板同时看旧版本样本占比与奖励分数分布偏移，一旦偏移超出训练侧容忍带就缩窗。这里不适用“照搬原窗口”的做法，因为传播时延与模型规模、拓扑档位强相关。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-52\">五十二 · 量化迁移：NVFP4 采样稳定性的领域敏感性</h3>\n<p>量化方案在 NVFP4 与 FP8 间按采样稳定性选择，这条规则迁到新领域时不能默认沿用。采样稳定性本质是低精度下 logits 分布的尾部保真度：NVFP4 的块缩放粒度更粗，对长尾 token 的概率质量压缩更明显。在开放式对话里这种压缩通常被采样温度掩盖；在需要精确复现格式（如结构化输出、工具调用参数）的领域，尾部 token 恰是决定合法性的关键，NVFP4 下的格式违规率会上升。机制上，rollout 引擎的采样核在 NVFP4 路径上要额外做一次合法性掩码校验，代价是每步多一次小算子启动，吞吐略降但避免整批重采样。</p>\n<p>迁移判断分档：B200/B300 单机档位可先以 FP8 跑基线，再用 NVFP4 做 A/B，把“采样稳定性”作为独立监控项而非附带指标；GB200 NVL72 档位因单卡显存相对宽裕，可对奖励模型保留 FP8、仅对生成侧试 NVFP4，避免奖励打分精度与生成精度同时劣化导致归因困难。可用事实未给出 NVFP4 实测，因此任何“NVFP4 更快”的表述在迁移文档里都必须标注为待核验，不能写成结论。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-53\">五十三 · 规模上限：长尾队列与批利用率的相互作用</h3>\n<p>长尾样本进低优先级队列是这套方案在规模上的主要约束点。随着并发上升，请求长度分布的尾部变厚，低优先级队列深度增长，主批的 token 预算被固定后，可组批的短请求逐渐耗尽，批利用率下降。设主批 token 预算为 <span>T<sub>b</sub></span>，队列中可用短请求的总 token 为 <span>S</span>，则批利用率的上界近似为：</p>\n<div class=\"formula\">$$\\eta \\le \\frac{\\min(S, T_b)}{T_b}$$</div>\n<p>当 <span>S</span> 长期小于 <span>T<sub>b</sub></span>，GPU 在固定批大小下空转，这正是解耦想避免却无法消除的代价。规模上限不在显存，而在“短请求供给速率”与“长尾消化速率”的平衡点。迁到请求长度分布更偏长的领域（如长文档摘要、多轮工具链），这个平衡点会显著前移，固定批大小的策略失效，需要改成按长度分桶的多队列组批，代价是调度器复杂度上升与跨桶批利用率不均。工程判断：先用监控的长尾队列深度做容量规划输入，把并发上限设为使队列深度稳定的值，而不是按峰值吞吐倒推。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-54\">五十四 · 不适用的场景与失败模式迁移</h3>\n<p>三类场景应明确判定为不适用。其一，奖励必须在线交互获取的领域（如多轮对话中的用户反馈），奖励池无法与生成重叠，解耦收益归零，异步流水线退化为串行。其二，生成与验证共享同一模型的场景，独立 serving 池会重复占用显存，KV 前缀无法跨池共享，独立扩容反而降低整体显存效率。其三，对样本新鲜度要求极高的在线学习，短窗口 staleness 直接违反语义，旧版本在途请求会污染训练分布。</p>\n<p>失败模式迁移时要注意放大效应：KV 缓存击穿导致预填尖峰，在长提示占比高的领域会被放大，因为单次预填的算力代价更高；奖励池排队反压生成，在 <span>τ<sub>score</sub></span> 尾部长的领域会从偶发变成常态；权重同步窗口过长引入旧版本样本，在快速迭代的小步长训练里更易触发。迁移文档应把这三条写成显式的准入检查项，而不是留在监控面板里等告警。可用事实未给出阈值，因此检查项只能定义为“观测到即降并发或缩窗”的定性规则，具体数值留给部署方按自身 SLO 标定。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-55\">五十五 · 迁移的工程判断：先改队列，再改精度</h3>\n<p>把 ESSA 推理方案迁到新模型或新领域，改动顺序应是队列语义优先于数值精度。理由在于：解耦架构的收益主要来自组批与重叠，而组批的正确性由队列分级与背压策略决定；量化只影响单请求的采样质量与单卡吞吐，属于二阶项。迁到新领域时先重算 <span>N<sub>rm</sub></span> 与长尾队列的平衡点，确认奖励池不会反压生成，再决定 NVFP4 是否可用。若顺序颠倒，先调精度再调队列，会把采样稳定性问题与批利用率问题混在一起，归因困难。</p>\n<p>最后落在一条可执行的机制上：迁移验收应包含三个观测量的联合判据——KV 命中率不低于基线领域水平、长尾队列深度在并发上限内收敛、旧版本样本占比在 staleness 窗口内可解释。三者任一不满足，说明该领域或该模型族超出了这套方案的适用边界，应退回耦合式 rollout 或改用更短的同步窗口，而不是靠堆副本硬撑。</p>\n\n<h3 id=\"paper-essa-evolutionary-strategies-for-sca-2025-sec-56\">五十六 · 迁移边界：ES 解耦架构在换模型、换领域、换档位时的失效条件</h3>\n\n<p>ESSA 的推理架构能否迁移，取决于一个前提是否成立：<strong>策略改进信号可以被“批量采样 + 独立打分”充分表达，而不依赖梯度步节奏与生成过程的细粒度耦合</strong>。这个前提在纯文本对齐任务上成立，因为奖励模型对一条完整序列给出标量分数即可构成 ES 的适应度 F(θ+ε)；但一旦迁到需要<strong>过程级监督</strong>的领域——多步工具调用、代码执行反馈、长程 agent 轨迹——奖励就不再是序列末端的单一标量，而是依赖中间状态的可验证结果。此时 rollout 引擎的“固定 token 预算组主批”假设失效：一条轨迹的有效长度由环境返回决定而非提示词长度分布决定，长尾队列的深度不再由提示词长度刻画，低优先级队列的排序键必须换成“预计环境交互轮数”，否则主批会被少数超长轨迹拖到批利用率崩塌。迁移到这类领域时，KV 前缀共享的命中率也会显著下降，因为每轮工具返回都改写上下文前缀，前缀哈希几乎不重复，预填代价重新回到主导地位——这正是 KV 缓存击穿导致预填尖峰的失败模式在 agent 场景下的放大版本。</p>\n\n<p>规模上限由三个耦合约束共同决定，可以写成一个粗略的可行性判据。设单批 token 预算为 B、长尾队列允许的最大等待时间为 W、权重版本切换窗口为 S，则吞吐受限于：</p>\n\n<div class=\"formula\">$$\\text{Throughput}_{\\max}\\approx\\frac{B\\cdot \\eta_{\\text{batch}}}{T_{\\text{prefill}}(1-h)+T_{\\text{decode}}},\\quad \\text{s.t.}\\ \\eta_{\\text{batch}}\\ge 1-\\frac{D_{\\text{tail}}}{B},\\ \\ S\\le W$$</div>\n\n<p>其中 h 为前缀 KV 命中率、η_batch 为批利用率、D_tail 为长尾样本占用预算。迁移到新模型时，h 随提示词模板复用度变化，D_tail 随任务长度方差变化，而 S 受训练侧消费速度约束。三者中任一越界，解耦架构的收益就被抵消：h 低则预填主导、独立组批失去意义；D_tail 高则主批空转、固定 SLO 无法维持；S 超过 W 则旧权重在途请求污染样本池，ES 的适应度估计被系统性偏置。判断一个迁移是否可行，不是看模型参数量，而是看这三个量能否在新领域里被监控并压住——材料明确指出 staleness 上界与长尾拖尾阈值均未量化，因此任何跨领域迁移都必须先补这两项测量，而不是直接复用 B200 档位的组批参数。</p>\n\n<p>量化档位的迁移风险集中在 NVFP4 采样稳定性上，且这一风险与 ES 的扰动机制叠加放大。ES 的梯度估计依赖对 θ+ε 的多次独立采样求期望，若 NVFP4 在低概率 token 上的舍入误差使采样分布发生偏移，则 F(θ+ε) 的方差被抬高，等效于给梯度估计注入额外噪声，收敛所需的采样批量随之上升——这与“固定批大小独立调度”的吞吐优势直接冲突。迁移到 B300 或 GB200 NVL72 时，档位切换改变的是并行拓扑与每卡显存预算，KV 前缀缓存的 LRU 淘汰策略需按新档位的显存上限重算容量，否则命中率 h 会在档位切换后骤降。可操作的工程判断是：<strong>把 NVFP4 与 FP8 的选择做成按模型与领域可配置的开关，并以采样分布偏移作为独立监控项</strong>，而不是按硬件档位一刀切；奖励池独立扩容的容量规划也要按新领域的打分延迟重估，因为奖励模型排队反压生成是解耦架构最直接的失效路径——打分慢于生成时，队列解耦只是把空转从 rollout 引擎转移到奖励池，整体 SLO 并不会改善。</p>\n\n<table class=\"mini\">\n<thead><tr><th>迁移维度</th><th>成立条件</th><th>失效表现</th><th>需补测量</th></tr></thead>\n<tbody>\n<tr><td>换模型</td><td>提示词模板复用度高，h 可维持</td><td>前缀哈希不重复，预填尖峰</td><td>命中率随模板变化的曲线</td></tr>\n<tr><td>换领域（agent/工具）</td><td>奖励可退化为序列级标量</td><td>长尾队列排序键失效，批利用率崩塌</td><td>轨迹长度方差与 D_tail</td></tr>\n<tr><td>换量化档位</td><td>NVFP4 采样偏移可控</td><td>F 方差抬高，需增大采样批量</td><td>采样分布偏移与 ES 方差</td></tr>\n<tr><td>换硬件档位</td><td>KV 缓存容量按新显存重算</td><td>LRU 淘汰过早，h 骤降</td><td>档位切换后命中率</td></tr>\n</tbody>\n</table>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">ESSA: Evolutionary </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Strategies for Scala…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · ESSA: Evolutionary Stra… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>未给出</td></tr><tr><td>基线</td><td>未给出</td></tr><tr><td>主要结果</td><td>材料未给出具体数据集与基线数字；可核验的机制点是rollout引擎与训练解…</td></tr><tr><td>消融</td><td>材料未给出消融实验；可讨论的消融维度包括KV前缀共享开关、奖励池独立ser…</td></tr><tr><td>局限</td><td>材料未给出规模与硬件档位实测；NVFP4下采样稳定性、长尾样本拖尾对批利用…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-essa-evolutionary-strategies-for-sca-2025 · 共 9 个片段</p>\n";break;}}})();
